Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module NESKA.

(* [comment removed for export] *)
(* [comment removed for export] *)
Record sink_policyA : Type := SPA {
  spa_mode : Prop;          (* [comment removed for export] *)
  spa_cap : Z -> Prop;      (* [comment removed for export] *)
  spa_nmax : Z;             (* [comment removed for export] *)
  spa_pot : Z -> credit;    (* [comment removed for export] *)
  spa_hb : Z -> Prop        (* [comment removed for export] *)
}.

Record sink_policyA_ok (L : asan_layout) (P : sink_policyA) : Prop := SPAO {
  spao_pot_nonneg : forall c, NESK.is_cap c -> 0 <= c <= spa_nmax P -> 0 <= fst (spa_pot P c) /\ 0 <= snd (spa_pot P c);
  spao_hb_mono : forall h h', spa_hb P h -> h' <= h -> spa_hb P h';
  (* [comment removed for export] *)
  spao_next : forall c h, NESK.is_cap c -> (0 < c -> spa_cap P c) -> spa_hb P h -> c <= h ->
              0 < NESK.cap_next c <= spa_nmax P
              /\ acredit_ok L (spa_pot P c) (NESK.cap_next c)
              /\ PMSP.credit_le (spa_pot P (NESK.cap_next c)) (adebit L (spa_pot P c) (NESK.cap_next c));
  spao_nmax_pos : 0 < spa_nmax P;
  (* [comment removed for export] *)
  spao_cap_next : forall c, NESK.is_cap c -> (0 < c -> spa_cap P c) -> spa_cap P (NESK.cap_next c)
}.

(* [comment removed for export] *)
(* [comment removed for export] *)
Section WithImage.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable AA : pm_asan_addrs.
Variable E : ne_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.

Abbreviation accA := PMSPA.accA.
Abbreviation annA := PMSPA.annA.
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation ffroomA := PMSPA.ffroomA.
Abbreviation ffrsA := PMSPA.ffrsA.
Abbreviation aobjA := PMSPA.aobjA.
Abbreviation pm_scr := PMSPA.pm_scr.
Abbreviation cfg := (@PMSPA.cfg segs).

(* [comment removed for export] *)
Definition sink_atA (P : sink_policyA) (M : word -> option byte) (o : Z) (k : NESK.sink) : Prop :=
  L5.u64_at segs M o (NESK.sk_b k) /\ L5.u64_at segs M (o + 8) (NESK.sk_b k + NESK.sk_z k) /\ L5.u64_at segs M (o + 16) (NESK.sk_b k + NESK.sk_c k)
  /\ L5.defined M o 24 /\ accA M o 24
  /\ 0 <= NESK.sk_z k <= NESK.sk_c k /\ NESK.is_cap (NESK.sk_c k)
  /\ (NESK.sk_c k = 0 -> NESK.sk_b k = 0)
  /\ (0 < NESK.sk_c k ->
        L5.defined M (NESK.sk_b k) (NESK.sk_c k) /\ accA M (NESK.sk_b k) (NESK.sk_z k) /\ annA M (NESK.sk_b k) (NESK.sk_z k) (NESK.sk_c k)
        /\ ablock_range L ar (NESK.sk_b k) (NESK.sk_c k) /\ spa_cap P (NESK.sk_c k)
        /\ NESK.sk_c k <= spa_nmax P).

Lemma sink_potA_nonneg P M o k : sink_policyA_ok L P -> sink_atA P M o k -> 0 <= fst (spa_pot P (NESK.sk_c k)) /\ 0 <= snd (spa_pot P (NESK.sk_c k)).
