Section Model.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable AA : pm_asan_addrs.
Variable E : ne_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable vp_adaptor : Z.

Abbreviation accA := PMSPA.accA.
Abbreviation annA := PMSPA.annA.
Abbreviation HV := (PMSPA.HV L ar).
Abbreviation scA := (PMSPA.scA L).

(* [comment removed for export] *)
Definition enc_atA (M : word -> option byte) (ov osk : Z) (en : enc) : Prop :=
  L5.u64_at segs M ov (ne_vt E) /\ L5.u64_at segs M (ov + 8) osk /\ L5.u32_at segs M (ov + 16) MAX_DEPTH
  /\ L5.u64_at segs M (ov + 24) (en_b en)
  /\ L5.u64_at segs M (ov + 32) (en_b en + ESZ * en_n en)
  /\ L5.u64_at segs M (ov + 40) (en_b en + ESZ * ecap (en_k en))
  /\ L5.u32_at segs M (ov + 48) (en_depth en)
  /\ L5.defined M ov ESIZE /\ accA M ov ESIZE
  /\ 0 <= en_k en <= EKMAX /\ 0 <= en_depth en <= en_n en /\ en_n en <= ecap (en_k en)
  /\ (en_k en = 0 -> en_b en = 0)
  /\ (0 < en_k en ->
        en_b en mod 8 = 0 /\ L5.defined M (en_b en) (ESZ * ecap (en_k en)) /\ ablock_range L ar (en_b en) (ESZ * ecap (en_k en))
        /\ accA M (en_b en) (ESZ * en_n en) /\ annA M (en_b en) (ESZ * en_n en) (ESZ * ecap (en_k en))).

(* [comment removed for export] *)
Record aest : Type := AEST { ae_a : PQMA.ast; ae_kbb : list Z; ae_e : enc; ae_s : NESK.sink }.
Definition ndest (lv : list PQMA.alvl) : Z := Z.of_nat (length (List.filter (fun x => PQMA.lv_t x =? 0) lv)) - 1.
Definition nlv (st : aest) : Z := PQMA.nlv (ae_a st).
Definition kbsize (st : aest) : Z := PQMA.kbsize (ae_a st).
Definition zsize (st : aest) : Z := NESK.sk_z (ae_s st).
Definition esize (st : aest) : Z := en_n (ae_e st).
Definition edepth (st : aest) : Z := en_depth (ae_e st).
Definition phi (st : aest) : Z := zsize st + kbsize st.

Definition ae_atA (M : word -> option byte) (oa ov osk : Z) (st : aest) : Prop :=
  PQMA.adaptor_at segs A accA annA vp_adaptor M oa ov (ae_a st)
  /\ kcontent segs M (oa + PQMA.AOFF_KB) (PQMA.a_kb (ae_a st)) (ae_kbb st)
  /\ enc_atA M ov osk (ae_e st)
  /\ NESKA.sink_atA segs L ar (NESKA.PMEA L) M osk (ae_s st).
Definition ae_ok (st : aest) : Prop :=
  PQMA.adaptor_ok (ae_a st) /\ utf8_valid (ae_kbb st) = true /\ en_depth (ae_e st) = ndest (PQMA.a_lv (ae_a st)).
Definition aeown (st : aest) : list (Z * Z) := PQMA.aown (ae_a st) ++ enc_own (ae_e st) ++ NESK.sink_own (ae_s st).
Definition ae_WA (oa ov osk oec : Z) : list L5.range :=
  PQMA.adaptor_W A oa ++ enc_W ov ++ [(osk, 24); (oec, 16)] ++ PMSP.err_W A.
(* [comment removed for export] *)
Definition pot_aeA (st : aest) : credit :=
  PM.credit_add (scA (PQMA.pot_adaptor HV (ae_a st)))
    (PM.credit_add (scA (pot_estack HV (en_k (ae_e st)))) (NESKA.spa_pot (NESKA.PMEA L) (NESK.sk_c (ae_s st)))).
Definition pot_encA (en : enc) (k : NESK.sink) : credit :=
  PM.credit_add (scA (pot_estack HV (en_k en))) (NESKA.spa_pot (NESKA.PMEA L) (NESK.sk_c k)).

(* [comment removed for export] *)
Definition ec_stateA (M : word -> option byte) (oec : Z) (b : bool) (cat : Z) : Prop :=
  if b then exists v, 1 <= v <= 64 /\ PMSPA.ec_at segs M oec v (pa_errcat_obj A) else PMSPA.ec_at segs M oec 0 cat.

End Model.

(* [comment removed for export] *)
Definition oacct (n : Z) (s : PQMA.mpst) (st : aest) (sm : PM.strm) : Prop :=
  phi st + 6 * nlv st + 8 * PM.unread (PQMA.p_src s) sm <= 8 * n + 6 /\ 0 <= n < 2 ^ 26.
Definition oacct_d (d n : Z) (s : PQMA.mpst) (st : aest) (sm : PM.strm) : Prop :=
  phi st + 6 * nlv st + 8 * PM.unread (PQMA.p_src s) sm + d <= 8 * n + 6 /\ 0 <= n < 2 ^ 26.
Lemma oacct_d0 n s st sm : oacct n s st sm <-> oacct_d 0 n s st sm.
Proof. unfold oacct, oacct_d. lia. Qed.
Lemma oacct_consume d n s s' st sm sm' c :
  oacct_d d n s st sm -> 0 <= c -> PM.unread (PQMA.p_src s') sm' <= PM.unread (PQMA.p_src s) sm - c -> oacct_d (d + 8 * c) n s' st sm'.
Proof. unfold oacct_d. lia. Qed.
Lemma oacct_val d n s st st' sm :
  oacct_d d n s st sm -> nlv st' = nlv st -> phi st' <= phi st + d -> oacct n s st' sm.
Proof. unfold oacct, oacct_d. lia. Qed.
Lemma oacct_push d dphi n s st st' sm :
  oacct_d d n s st sm -> nlv st' = nlv st + 1 -> phi st' <= phi st + dphi -> dphi + 6 <= d -> oacct n s st' sm.
Proof. unfold oacct, oacct_d. lia. Qed.
Lemma oacct_pop d n s st st' sm :
  oacct_d d n s st sm -> nlv st' = nlv st - 1 -> phi st' <= phi st + 6 + d -> oacct n s st' sm.
Proof. unfold oacct, oacct_d. lia. Qed.
Lemma oacct_bounds d n s st sm :
  oacct_d d n s st sm -> 0 <= PM.unread (PQMA.p_src s) sm -> 0 <= kbsize st -> 0 <= zsize st -> 1 <= nlv st ->
  zsize st + d <= NESK.SMZ /\ phi st + d <= 8 * n.
Proof. unfold oacct_d, phi, NESK.SMZ. intros. change (2 ^ 26) with 67108864 in *. change (2 ^ 29) with 536870912. lia. Qed.
(* [comment removed for export] *)
Lemma oacct_pop_room n s st sm :
  oacct n s st sm -> 0 <= PM.unread (PQMA.p_src s) sm -> 2 <= nlv st -> phi st + 6 <= NESK.SMZ.
Proof. unfold oacct, NESK.SMZ. intros. change (2 ^ 26) with 67108864 in *. change (2 ^ 29) with 536870912. lia. Qed.
Lemma oacct_val_room d n s st sm :
  oacct_d d n s st sm -> 0 <= PM.unread (PQMA.p_src s) sm -> 0 <= kbsize st -> 1 <= nlv st -> zsize st + d <= NESK.SMZ.
Proof. unfold oacct_d, phi, NESK.SMZ. intros. change (2 ^ 26) with 67108864 in *. change (2 ^ 29) with 536870912. lia. Qed.

(* [comment removed for export] *)
Definition cpl (s : PQMA.mpst) (st : aest) : Prop := PQMA.cpl s (ae_a st).
Definition bal (st : aest) : Prop := esize st = edepth st.
Definition ebound (st : aest) : Prop := esize st <= MAX_DEPTH.

Lemma filter_length_le {T} (f : T -> bool) (l : list T) : (length (List.filter f l) <= length l)%nat.
Proof. induction l as [|x t IH]; cbn; [lia|]. destruct (f x); cbn; lia. Qed.
Lemma ndest_le lv : ndest lv <= Z.of_nat (length lv) - 1.
Proof. unfold ndest. pose proof (filter_length_le (fun x => PQMA.lv_t x =? 0) lv). lia. Qed.
Lemma edepth_room st : ae_ok st -> nlv st <= MAX_DEPTH -> edepth st + 1 <= MAX_DEPTH.
Proof.
  intros (_ & _ & CP) Hn. unfold edepth, nlv, PQMA.nlv, MAX_DEPTH, PQM.MAX_DEPTH in *. rewrite CP. pose proof (ndest_le (PQMA.a_lv (ae_a st))). lia.
Qed.
Lemma ebound_of_bal st : ae_ok st -> bal st -> nlv st <= MAX_DEPTH + 1 -> ebound st.
Proof.
  intros (_ & _ & CP) B Hn. unfold ebound, bal, esize, edepth, nlv, PQMA.nlv, MAX_DEPTH, PQM.MAX_DEPTH in *. rewrite B, CP.
  pose proof (ndest_le (PQMA.a_lv (ae_a st))). lia.
Qed.
Lemma ndest_app x lv : ndest (lv ++ [x]) = ndest lv + (if PQMA.lv_t x =? 0 then 1 else 0).
Proof. unfold ndest. rewrite List.filter_app, List.length_app. cbn. destruct (PQMA.lv_t x =? 0); cbn; lia. Qed.
Lemma ndest_removelast lv x : lv <> [] -> last lv PQMA.lv_root = x -> ndest (removelast lv) = ndest lv - (if PQMA.lv_t x =? 0 then 1 else 0).
Proof. intros Hne Hl. rewrite (app_removelast_last PQMA.lv_root Hne) at 2. rewrite Hl, ndest_app. lia. Qed.
Lemma ndest_kinds lv lv' : List.map PQMA.lv_t lv = List.map PQMA.lv_t lv' -> ndest lv = ndest lv'.
Proof.
  intros H. unfold ndest. do 2 f_equal.
  revert lv' H. induction lv as [|x t IH]; intros [|y u] H; cbn in H; try discriminate; [reflexivity|].
  injection H as Hx Ht. cbn [List.filter]. rewrite Hx. specialize (IH u Ht). cbn in IH |- *.
  destruct (PQMA.lv_t y =? 0); cbn; [f_equal|]; exact IH.
Qed.
Lemma ndest_head_nonneg l : l <> [] -> nth 0 l PQMA.lv_root = PQMA.lv_root -> 0 <= ndest l.
Proof.
  intros Hne H0. unfold ndest. destruct l as [|y u]; [congruence|]. cbn [nth] in H0. subst y.
  cbn [List.filter PQMA.lv_t PQMA.lv_root Z.eqb]. cbn [length]. rewrite Nat2Z.inj_succ. lia.
Qed.
Lemma ndest_top_dest lv x :
  (2 <= length lv)%nat -> nth 0 lv PQMA.lv_root = PQMA.lv_root -> last lv PQMA.lv_root = x -> PQMA.lv_t x = 0 -> 1 <= ndest lv.
Proof.
  intros Hl H0 Hx Ht.
  assert (Hne : lv <> []) by (destruct lv; cbn in Hl; [lia|congruence]).
  pose proof (ndest_removelast lv x Hne Hx) as R. rewrite Ht in R. cbn in R.
  assert (Hr : removelast lv <> [] /\ nth 0 (removelast lv) PQMA.lv_root = PQMA.lv_root).
  { destruct lv as [|y [|z u]]; cbn in Hl; [lia|lia|]. cbn [nth] in H0. subst y. split; [cbn; congruence|reflexivity]. }
  destruct Hr as [Hr1 Hr2]. pose proof (ndest_head_nonneg (removelast lv) Hr1 Hr2). lia.
Qed.
Lemma eend_room st : ae_ok st -> 1 <= ndest (PQMA.a_lv (ae_a st)) -> 1 <= edepth st.
Proof. intros (_ & _ & CP) H. unfold edepth. rewrite CP. exact H. Qed.

End NEMA.

