Abbreviation scA := (PMSPA.scA L).
Abbreviation enc_atA := (NEMA.enc_atA segs E L ar).
Abbreviation sink_atA := (NESKA.sink_atA segs L ar P).
Abbreviation ec_stateA := (NEMA.ec_stateA segs A).
