(* [comment removed for export] *)
Definition pot_encA (en : enc) (k : NESK.sink) : credit := PM.credit_add (scA (pot_estack HV (en_k en))) (NESKA.spa_pot P (NESK.sk_c k)).

(* [comment removed for export] *)
Definition view_okA (M : word -> option byte) (FF : list fframe) (LBX : list (Z * Z)) (ov osk p d n : Z) : Prop :=   (* [comment removed for export] *)
  L5.u64_at segs M p d /\ L5.u64_at segs M (p + 8) n /\ 0 <= n < 2 ^ 29 /\ L5.defined M d n   (* [comment removed for export] *)
  /\ aobjA FF p 16   (* [comment removed for export] *)
  /\ accA M p 16 /\ accA M d n /\ (n = 0 \/ PGS.in_blk LBX d n \/ aobjA FF d n)
  /\ (p + 16 <= ov \/ ov + 56 <= p) /\ (d + n <= ov \/ ov + 56 <= d)
  /\ (p + 16 <= osk \/ osk + 24 <= p) /\ (d + n <= osk \/ osk + 24 <= d)   (* [comment removed for export] *)
  /\ 0 <= d /\ d + n <= 2 ^ 47.

