(* [comment removed for export] *)
Definition eslot_specA (pc h : Z)
           (args : eargs -> list fframe -> bvmap 5 word -> (word -> option byte) -> Z -> Z -> Z -> list (Z * Z) -> Prop)
           (pre : eargs -> enc -> NESK.sink -> Prop)
           (step : eargs -> enc -> NESK.sink -> bool -> enc -> NESK.sink -> bool -> Prop) : Prop :=
  NESKA.spa_mode P ->
  forall (a : eargs) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r ov osk oec cat : Z) (en : enc) (k : NESK.sink) (b e : bool),
    ri_inv HI (eown en k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r h -> ffroomM h FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 ov -> args a FF R M osk ov oec LBX ->   (* [comment removed for export] *)
    aobjA FF ov 56 -> ov mod 8 = 0 -> aobjA FF osk 24 -> osk mod 8 = 0 -> aobjA FF oec 16 -> oec mod 8 = 0 ->
    (ov + 56 <= osk \/ osk + 24 <= ov) -> (oec + 16 <= ov \/ ov + 56 <= oec) -> (oec + 16 <= osk \/ osk + 24 <= oec) ->
    enc_atA M ov osk en -> sink_atA M osk k -> ec_stateA M oec b cat -> PMSTA.base_okA segs A M -> err_okA M e ->
    pre a en k ->
    PMSP.credit_le (pot_encA en k) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
            (en' : enc) (k' : NESK.sink) (b' e' : bool) (cr' : credit),
        regs_preserved R R' ->
        enc_atA M' ov osk en' -> sink_atA M' osk k' -> ec_stateA M' oec b' cat -> PMSTA.base_okA segs A M' -> err_okA M' e' ->
        (b = true -> b' = true) -> (e = true -> e' = true) -> step a en k b en' k' b' ->
        L5CA.ahpres L ar LBX FF sp (pm_scr h) (W_enc A ov osk oec) M M' ->
        PMSP.credit_keep cr cr' (pot_encA en k) (pot_encA en' k') ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (eown en' k' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

