(* [comment removed for export] *)
Definition aargs_of (f : eargs -> bvmap 5 word -> (word -> option byte) -> Z -> Z -> Z -> list (Z * Z) -> Prop)
           (a : eargs) (FF : list fframe) (R : bvmap 5 word) (M : word -> option byte) (sp ov oec : Z) (LBX : list (Z * Z)) : Prop :=
  f a R M sp ov oec LBX.
(* [comment removed for export] *)
Definition aargs_str (a : eargs) (FF : list fframe) (R : bvmap 5 word) (M : word -> option byte) (osk ov oec : Z) (LBX : list (Z * Z)) : Prop :=   (* [comment removed for export] *)
  exists p d, getr R 11%bv = Z_to_bv 64 p /\ view_okA M FF LBX ov osk p d (ea_n a)
  /\ getr R 12%bv = Z_to_bv 64 (ea_tag a) /\ (ea_tag a = TAG_NONE \/ ea_tag a = TAG_ENANO) /\ getr R 14%bv = Z_to_bv 64 oec
  /\ (ea_tag a = TAG_NONE -> L5.bytes_at segs M d (ea_bs a) /\ Z.of_nat (length (ea_bs a)) = ea_n a /\ utf8_valid (ea_bs a) = true /\ bytes_ok (ea_bs a))
  /\ (ea_tag a = TAG_ENANO -> ea_n a <= 31).   (* [comment removed for export] *)
Definition aargs_key (a : eargs) (FF : list fframe) (R : bvmap 5 word) (M : word -> option byte) (osk ov oec : Z) (LBX : list (Z * Z)) : Prop :=   (* [comment removed for export] *)
  exists p d, getr R 11%bv = Z_to_bv 64 p /\ view_okA M FF LBX ov osk p d (ea_n a)
  /\ getr R 13%bv = Z_to_bv 64 oec
  /\ L5.bytes_at segs M d (ea_bs a) /\ Z.of_nat (length (ea_bs a)) = ea_n a /\ utf8_valid (ea_bs a) = true /\ bytes_ok (ea_bs a).
Definition aargs_bstr (a : eargs) (FF : list fframe) (R : bvmap 5 word) (M : word -> option byte) (osk ov oec : Z) (LBX : list (Z * Z)) : Prop :=   (* [comment removed for export] *)
  exists p d, getr R 11%bv = Z_to_bv 64 p /\ view_okA M FF LBX ov osk p d (ea_n a) /\ getr R 14%bv = Z_to_bv 64 oec.

