Definition ntb_specA (W pc : Z) : Prop :=
  NESKA.spa_mode P ->
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r q osk : Z) (k : NESK.sink),
    ri_inv HI (NESK.sink_own k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r 2 -> ffroomM 2 FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 11%bv = Z_to_bv 64 q -> L5.u64_at segs M q osk -> aobjA FF q 8 -> q mod 8 = 0 -> accA M q 8 -> (q + 8 <= osk \/ osk + 24 <= q) ->   (* [comment removed for export] *)
    aobjA FF osk 24 -> osk mod 8 = 0 -> sink_atA M osk k ->
    NESK.sk_z k + W <= NESK.SMZ ->
    PMSP.credit_le (NESKA.spa_pot P (NESK.sk_c k)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (k' : NESK.sink) (cr' : credit),
        regs_preserved R R' ->
        sink_atA M' osk k' -> NESK.sk_z k' = NESK.sk_z k + W ->
        L5CA.ahpres L ar LBX FF sp (pm_scr 2) [(osk, 24)] M M' ->
        PMSP.credit_keep cr cr' (NESKA.spa_pot P (NESK.sk_c k)) (NESKA.spa_pot P (NESK.sk_c k')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (NESK.sink_own k' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

