Definition wsv_specA : Prop :=
  NESKA.spa_mode P ->
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r ov osk p d n : Z) (bs : list Z) (en : enc) (k : NESK.sink),
