    aobjA FF ov 56 -> ov mod 8 = 0 -> aobjA FF osk 24 -> osk mod 8 = 0 -> (ov + 56 <= osk \/ osk + 24 <= ov) ->
    enc_atA M ov osk en -> sink_atA M osk k -> PMSTA.base_okA segs A M ->
