Abbreviation cfg := (@PMSP.cfg segs).

Definition eslot_specF (pc h : Z)
           (args : eargs -> list fframe -> bvmap 5 word -> (word -> option byte) -> Z -> Z -> Z -> list (Z * Z) -> Prop)
           (pre : eargs -> enc -> NESK.sink -> Prop)
           (step : eargs -> enc -> NESK.sink -> bool -> enc -> NESK.sink -> bool -> Prop) : Prop :=
  NESKA.spa_mode P ->
  forall (a : eargs) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r ov osk oec cat : Z) (en : enc) (k : NESK.sink) (b e : bool)
         (D : list (list Z)) (RC : list Z),
    ri_inv (HIk D) (eown en k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r h -> PGSA.ffroomB PQRA.FCM h FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
    HAR.rchain L ar M sp (bv_unsigned (getr R 8%bv)) RC -> bv_unsigned (getr R 8%bv) <> sp + 8 ->   (* [comment removed for export] *)
    getr R 10%bv = Z_to_bv 64 ov -> args a FF R M osk ov oec LBX ->   (* [comment removed for export] *)
    PMSPA.aobjA FF ov 56 -> ov mod 8 = 0 -> PMSPA.aobjA FF osk 24 -> osk mod 8 = 0 -> PMSPA.aobjA FF oec 16 -> oec mod 8 = 0 ->
    (ov + 56 <= osk \/ osk + 24 <= ov) -> (oec + 16 <= ov \/ ov + 56 <= oec) -> (oec + 16 <= osk \/ osk + 24 <= oec) ->
    NEMA.enc_atA segs E L ar M ov osk en -> NESKA.sink_atA segs L ar P M osk k -> NEMA.ec_stateA segs A M oec b cat ->
    PMSTA.base_okA segs A M -> PQSTA.err_okA segs A AA AQ M e ->
    pre a en k ->
    PMSP.credit_le (PM.credit_add (pot_encA L ar P en k) (tspE (ea_tag a) r D RC)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
            (en' : enc) (k' : NESK.sink) (b' e' : bool) (cr' : credit) (D' : list (list Z)),
        regs_preserved R R' ->
        NEMA.enc_atA segs E L ar M' ov osk en' -> NESKA.sink_atA segs L ar P M' osk k' -> NEMA.ec_stateA segs A M' oec b' cat ->
        PMSTA.base_okA segs A M' -> PQSTA.err_okA segs A AA AQ M' e' ->
        (b = true -> b' = true) -> (e = true -> e' = true) -> step a en k b en' k' b' ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr h) (W_enc A ov osk oec) M M' ->
        PMSP.credit_keep cr cr' (PM.credit_add (pot_encA L ar P en k) (tspE (ea_tag a) r D RC)) (PM.credit_add (pot_encA L ar P en' k') (tspE (ea_tag a) r D' RC)) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> incl D D' ->
        ri_inv (HIk D') (eown en' k' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

Definition v_string_specF : Prop :=
  eslot_specF (ne_string E) ENC_HS (aargs_str segs) pre_vstr step_str.   (* [comment removed for export] *)
