(* [comment removed for export] *)
Section Fam.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable AQ : pq_addrs.
Variable AA : pm_asan_addrs.
Variable E : ne_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HIk : list (list Z) -> asan_iface.
Variable tspV : Z -> list (list Z) -> list Z -> credit.   (* [comment removed for export] *)
Abbreviation cfg := (@PMSP.cfg segs).

Definition vis_specF (pc : Z)
           (args : bvmap 5 word -> (word -> option byte) -> list fframe -> list (Z * Z) -> Z -> Z -> Z -> Z -> Prop)   (* [comment removed for export] *)
           (pre : bvmap 5 word -> (word -> option byte) -> aest -> Prop)
           (step : bvmap 5 word -> (word -> option byte) -> aest -> aest -> bool -> bool -> Prop) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r oa ov osk oec cat : Z) (st : aest) (b e : bool)
         (D : list (list Z)) (RC : list Z),
    ri_inv (HIk D) (aeown st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r VIS_H -> PGSA.ffroomB PQRA.FCM VIS_H FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
    HAR.rchain L ar M sp (bv_unsigned (getr R 8%bv)) RC ->
    getr R 10%bv = Z_to_bv 64 oa -> args R M FF LBX oa ov osk oec ->
    PMSPA.aobjA FF oa PQMA.ASIZE -> oa mod 8 = 0 -> PMSPA.aobjA FF ov 56 -> ov mod 8 = 0 -> PMSPA.aobjA FF osk 24 -> osk mod 8 = 0 -> PMSPA.aobjA FF oec 16 -> oec mod 8 = 0 ->
    (oa + PQMA.ASIZE <= ov \/ ov + 56 <= oa) -> (oa + PQMA.ASIZE <= osk \/ osk + 24 <= oa) -> (oa + PQMA.ASIZE <= oec \/ oec + 16 <= oa) ->
    (ov + 56 <= osk \/ osk + 24 <= ov) -> (oec + 16 <= ov \/ ov + 56 <= oec) -> (oec + 16 <= osk \/ osk + 24 <= oec) ->
    NEMA.ae_atA segs A E L ar (qa_vp_adaptor AQ) M oa ov osk st -> PMSPA.accA M oa PQMA.ASIZE -> ae_ok st -> NEMA.ec_stateA segs A M oec b cat ->
    PMSTA.base_okA segs A M -> PQSTA.err_okA segs A AA AQ M e -> pre R M st ->
    PMSP.credit_le (PM.credit_add (NEMA.pot_aeA L ar st) (tspV (bv_unsigned (getr R 12%bv)) D RC)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z))
            (st' : aest) (b' e' : bool) (cr' : credit) (D' : list (list Z)),
        regs_preserved R R' ->
        NEMA.ae_atA segs A E L ar (qa_vp_adaptor AQ) M' oa ov osk st' -> ae_ok st' -> NEMA.ec_stateA segs A M' oec b' cat ->
        PMSTA.base_okA segs A M' -> PQSTA.err_okA segs A AA AQ M' e' ->
        (b = true -> b' = true) -> (e = true -> e' = true) -> step R M st st' b b' ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr VIS_H) (ae_WA A oa ov osk oec) M M' ->
        PMSP.credit_keep cr cr' (PM.credit_add (NEMA.pot_aeA L ar st) (tspV (bv_unsigned (getr R 12%bv)) D RC)) (PM.credit_add (NEMA.pot_aeA L ar st') (tspV (bv_unsigned (getr R 12%bv)) D' RC)) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> incl D D' ->
        ri_inv (HIk D') (aeown st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

Definition v_string_specF : Prop := vis_specF (qa_v_string AQ) (args_str segs) (pre_str segs) (step_str segs).
End Fam.

End PNVA.

End PnVisNA.
