Definition TSRES_ME : credit := PNRN.TSRES_ME.
Definition GS_H : Z := PNRN.GS_H.
Definition BEGIN_H : Z := PNRN.BEGIN_H.
Definition RI_H : Z := PNRN.RI_H.
Definition PARSE_H : Z := PNRN.PARSE_H.

Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
