Abbreviation accA := PMSPA.accA.
Abbreviation annA := PQRA.annA.
Abbreviation iss_at := (PM.iss_at segs A accA).
Abbreviation mparser_at := (PQMA.mparser_at segs A accA annA (pa_vp_parser A)).
Abbreviation ae_atA := (NEMA.ae_atA segs A E L ar (qa_vp_adaptor AQ)).
Abbreviation ec_stateA := (NEMA.ec_stateA segs A).
Abbreviation err_ok := (PQSTA.err_okA segs A AA AQ).
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation aobjA := PMSPA.aobjA.
Abbreviation ffrsA := PMSPA.ffrsA.
Abbreviation pm_scr := PMSPA.pm_scr.
Abbreviation cfg := (@PMSP.cfg segs).
Abbreviation HV := (PMSPA.HV L ar).
Abbreviation scA := (PMSPA.scA L).
Abbreviation FCM := PQRA.FCM.
Abbreviation ffroomM := (PGSA.ffroomB PQRA.FCM).
Abbreviation frame_okM := PQRA.frame_okM.
Abbreviation o_p := (PQRA.o_p A).
Abbreviation o_a := (PQRA.o_a A AQ).
Abbreviation o_v := (PQRA.o_v A).
Abbreviation o_is := (PQRA.o_is A).
Abbreviation o_ec := (PQRA.o_ec A).
Definition o_sink (fb : Z) : Z := fb + ne_off_sink E.

(* [comment removed for export] *)
Definition pot_runA (s : PQMA.mpst) (st : aest) : credit := PM.credit_add (scA (PQMA.pot_mparser HV s)) (pot_aeA L ar st).

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition mrun_pre (M : word -> option byte) (fb : Z) (s : PQMA.mpst) (st : aest) (str : PM.vstr) (sm : PM.strm) (e b : bool) (cat n : Z) : Prop :=
  mparser_at M (o_p fb) (o_is fb) s /\ ae_atA M (o_a fb) (o_v fb) (o_sink fb) st /\ iss_at M (o_is fb) str sm
  /\ L5.u64_at segs M (o_p fb + qa_off_vref AQ) (o_a fb)
  /\ accA M (o_p fb) 504 /\ accA M (o_v fb) 56 /\ accA M (o_sink fb) 24
  /\ PMSTA.base_okA segs A M /\ err_ok M e /\ ec_stateA M (o_ec fb) b cat
  /\ PQMA.mgrow_ok s /\ ae_ok st /\ PQMA.cpl s (ae_a st) /\ PQMA.acct n s (ae_a st) sm /\ oacct n s st sm
  /\ ebound st /\ (b = false -> bal st).
Definition mrun_fin (M : word -> option byte) (fb : Z) (s : PQMA.mpst) (st : aest) (str : PM.vstr) (sm : PM.strm) (e b : bool) (cat : Z) : Prop :=
  mparser_at M (o_p fb) (o_is fb) s /\ ae_atA M (o_a fb) (o_v fb) (o_sink fb) st /\ iss_at M (o_is fb) str sm
  /\ L5.u64_at segs M (o_p fb + qa_off_vref AQ) (o_a fb)
  /\ accA M (o_p fb) 504 /\ accA M (o_v fb) 56 /\ accA M (o_sink fb) 24
  /\ PMSTA.base_okA segs A M /\ err_ok M e /\ ec_stateA M (o_ec fb) b cat
  /\ PQMA.mgrow_ok s /\ ae_ok st.
Definition W_mrun (fb : Z) : list L5.range := PQRA.W_mrun A AQ fb ++ enc_W (o_v fb) ++ [(o_sink fb, 24)].
Definition mown (s : PQMA.mpst) (st : aest) : list (Z * Z) := PQMA.mparser_own s ++ aeown st.

Definition mprog := bvmap 5 word -> (word -> option byte) -> PQMA.mpst -> PQMA.mpst -> aest -> aest -> PM.strm -> PM.strm -> Prop.
Definition mrun_post_d (d : Z) (prog : mprog) (R' : bvmap 5 word) (M' : word -> option byte) (fb : Z) (s s' : PQMA.mpst)
           (st st' : aest) (str : PM.vstr) (sm sm' : PM.strm) (e e' b b' : bool) (cat n : Z) : Prop :=
  PMSP.src_step (PQMA.p_src s) (PQMA.p_src s') sm sm' /\ (e = true -> e' = true) /\ (b = true -> b' = true)
  /\ (   (b' = true /\ mrun_fin M' fb s' st' str sm' e' true cat)
      \/ (b' = false /\ mrun_pre M' fb s' st' str sm' e' false cat n /\ PQRA.minv_d d s' /\ prog R' M' s s' st st' sm sm' /\ PQRA.room_keep s s' sm sm')).

Definition mrun_spec_d (pc h d : Z) (args : bvmap 5 word -> Z -> PQMA.mpst -> aest -> PM.strm -> Z -> Prop) (prog : mprog) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb cat n : Z) (s : PQMA.mpst) (st : aest) (str : PM.vstr) (sm : PM.strm) (e b : bool),
    ri_inv HI (mown s st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r h -> ffroomM h FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    args R fb s st sm n ->
    mrun_pre M fb s st str sm e b cat n -> incl (PM.vs_own str) LBX -> PQRA.minv_d d s ->
    PMSP.credit_le (PM.credit_add (pot_runA s st) (scA TSRES_ME)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PQMA.mpst) (st' : aest)
            (sm' : PM.strm) (e' b' : bool) (cr' : credit),
        regs_preserved R R' ->
        mrun_post_d d prog R' M' fb s s' st st' str sm sm' e e' b b' cat n ->
        L5CA.ahpres L ar LBX FF sp (pm_scr h) (W_mrun fb) M M' ->
        PMSP.credit_keep cr cr' (pot_runA s st) (pot_runA s' st') ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
Definition mrun_spec (pc h : Z) (args : bvmap 5 word -> Z -> PQMA.mpst -> aest -> PM.strm -> Z -> Prop) (prog : mprog) : Prop :=
  mrun_spec_d pc h 0 args prog.

(* [comment removed for export] *)
Definition margs3 (R : bvmap 5 word) (fb : Z) (_ : PQMA.mpst) (_ : aest) (_ : PM.strm) (_ : Z) : Prop :=
  getr R 10%bv = Z_to_bv 64 (o_p fb) /\ getr R 11%bv = Z_to_bv 64 (o_a fb) /\ getr R 12%bv = Z_to_bv 64 (o_ec fb).
Definition margs_begin (P : Z -> Prop) (R : bvmap 5 word) (fb : Z) (s : PQMA.mpst) (st : aest) (sm : PM.strm) (n : Z) : Prop :=
  getr R 10%bv = Z_to_bv 64 (o_p fb) /\ getr R 11%bv = Z_to_bv 64 (o_a fb) /\ getr R 13%bv = Z_to_bv 64 (o_ec fb)
  /\ (exists t, P t /\ getr R 12%bv = Z_to_bv 64 t) /\ PQMA.acct_d 4 n s (ae_a st) sm /\ oacct_d 8 n s st sm.
(* [comment removed for export] *)
Definition margs_gs (t : Z) (R : bvmap 5 word) (fb : Z) (_ : PQMA.mpst) (_ : aest) (_ : PM.strm) (_ : Z) : Prop :=
  getr R 10%bv = Z_to_bv 64 (o_p fb) /\ getr R 12%bv = Z_to_bv 64 (o_ec fb) /\ getr R 11%bv = Z_to_bv 64 t.
(* [comment removed for export] *)
Definition gs_class (t len gsb : Z) : Prop :=
     (128 <= t <= 159 /\ gsb = 0 /\ 0 <= len <= 15)
  \/ (212 <= t <= 216 /\ gsb = 0 /\ 0 <= len <= 16)
  \/ ((t = 196 \/ t = 199 \/ t = 217) /\ gsb = 1 /\ 0 <= len)
  \/ ((t = 197 \/ t = 200 \/ t = 218 \/ t = 220 \/ t = 222) /\ gsb = 2 /\ 0 <= len)
  \/ ((t = 198 \/ t = 201 \/ t = 219 \/ t = 221 \/ t = 223) /\ gsb = 4 /\ 0 <= len).
(* [comment removed for export] *)
Lemma gs_class_hdr_cont t len gsb : gs_class t len gsb -> (128 <= t <= 159 \/ 220 <= t <= 223) -> hdr_cont len <= 1 + 2 * gsb.
Proof.
  intros C T. pose proof (hdr_cont_le len) as HB. unfold hdr_cont in *.
  destruct C as [C|[C|[C|[C|C]]]]; destruct C as (Ct & Eg & Cl); subst gsb;
  first [ lia
        | replace (len <=? 15) with true by (symmetry; apply Z.leb_le; lia); lia
        | destruct (len <=? 15); [lia|]; replace (len <=? 65535) with true by (symmetry; apply Z.leb_le; lia); lia ].
Qed.
Definition margs_ri (R : bvmap 5 word) (fb : Z) (s : PQMA.mpst) (st : aest) (sm : PM.strm) (n : Z) : Prop :=
  margs3 R fb s st sm n /\ PQRA.bb_room s sm.

Definition mprog_item : mprog := fun R' M' s s' st st' sm sm' =>
  PQRA.mpush_rel s s' /\ PM.unread (PQMA.p_src s') sm' < PM.unread (PQMA.p_src s) sm.
Definition mprog_push : mprog := fun R' M' s s' st st' sm sm' =>
  PQRA.mpush1 s s' /\ PM.unread (PQMA.p_src s') sm' <= PM.unread (PQMA.p_src s) sm.
Definition mprog_len (t : Z) : mprog := fun R' M' s s' st st' sm sm' =>
  PQMA.p_stk s' = PQMA.p_stk s /\ st' = st
  /\ exists len gsb, 0 <= len < 2 ^ 64 /\ getr R' 10%bv = Z_to_bv 64 len /\ gs_class t len gsb
     /\ PM.unread (PQMA.p_src s') sm' <= PM.unread (PQMA.p_src s) sm - gsb.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition gs_post_d (d t : Z) (R' : bvmap 5 word) (M' : word -> option byte) (fb : Z) (s s' : PQMA.mpst)
           (st st' : aest) (str : PM.vstr) (sm sm' : PM.strm) (e e' b b' : bool) (cat n : Z) : Prop :=
  PMSP.src_step (PQMA.p_src s) (PQMA.p_src s') sm sm' /\ (e = true -> e' = true) /\ (b = true -> b' = true)
  /\ (   (b' = true /\ mrun_fin M' fb s' st' str sm' e' true cat /\ PQMA.p_more s' = 0)
      \/ (b' = b /\ mrun_pre M' fb s' st' str sm' e' b cat n /\ PQRA.minv_d d s' /\ mprog_len t R' M' s s' st st' sm sm' /\ PQRA.room_keep s s' sm sm')).
Definition gs_spec_d (pc h d : Z) (args : bvmap 5 word -> Z -> PQMA.mpst -> aest -> PM.strm -> Z -> Prop) (t : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb cat n : Z) (s : PQMA.mpst) (st : aest) (str : PM.vstr) (sm : PM.strm) (e b : bool),
    ri_inv HI (mown s st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r h -> ffroomM h FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    args R fb s st sm n ->
    mrun_pre M fb s st str sm e b cat n -> incl (PM.vs_own str) LBX -> PQRA.minv_d d s ->
    PMSP.credit_le (PM.credit_add (pot_runA s st) (scA TSRES_ME)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PQMA.mpst) (st' : aest)
            (sm' : PM.strm) (e' b' : bool) (cr' : credit),
        regs_preserved R R' ->
        gs_post_d d t R' M' fb s s' st st' str sm sm' e e' b b' cat n ->
        L5CA.ahpres L ar LBX FF sp (pm_scr h) (W_mrun fb) M M' ->
        PMSP.credit_keep cr cr' (pot_runA s st) (pot_runA s' st') ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
Definition get_size_spec : Prop :=
  forall d t, 0 <= d <= 1 -> PQRA.gs_type t -> gs_spec_d (qa_get_size AQ) GS_H d (margs_gs t) t.
Definition begin_array_spec : Prop := mrun_spec (qa_begin_array AQ) BEGIN_H (margs_begin PQRA.ba_type) mprog_push.
Definition begin_object_spec : Prop := mrun_spec (qa_begin_object AQ) BEGIN_H (margs_begin PQRA.bo_type) mprog_push.
Definition read_item_spec : Prop := mrun_spec (qa_read_item AQ) RI_H margs_ri mprog_item.

Definition parse_post (M' : word -> option byte) (fb : Z) (s s' : PQMA.mpst) (st' : aest) (str : PM.vstr) (sm sm' : PM.strm)
           (e e' b' : bool) (cat : Z) : Prop :=
  mrun_fin M' fb s' st' str sm' e' b' cat /\ PMSP.src_step (PQMA.p_src s) (PQMA.p_src s') sm sm' /\ (e = true -> e' = true)
  /\ L5.defined M' (o_ec fb) 16.
Definition parse_spec : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r fb cat n : Z) (s : PQMA.mpst) (st : aest) (str : PM.vstr) (sm : PM.strm) (e : bool),
    ri_inv HI (mown s st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] -> entryA R M sp r PARSE_H -> ffroomM PARSE_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 -> frame_okM FF fb ->
    margs3 R fb s st sm n ->
    mrun_pre M fb s st str sm e false cat n -> incl (PM.vs_own str) LBX -> PQRA.minv s -> PQRA.bb_room s sm ->
    PMSP.credit_le (PM.credit_add (pot_runA s st) (scA TSRES_ME)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PQMA.mpst) (st' : aest)
            (sm' : PM.strm) (e' b' : bool) (cr' : credit),
        regs_preserved R R' ->
        parse_post M' fb s s' st' str sm sm' e e' b' cat ->
        L5CA.ahpres L ar LBX FF sp (pm_scr PARSE_H) (W_mrun fb) M M' ->
