  m_mem M1 model1 LK1 Aw1 s1 sa1 sm1 e1 cr1 b1 ->
  let MV := mrestrict (ahid Aw1 model1) M1 in
  L5.img_clear MV 65536 1409024
  /\ (7036928 <= F /\ F + B <= 2 ^ 47 /\ F mod 32 = 0 /\ (2147446784 + 17592186048512 <= F \/ F + B <= 2147446784) /\ 64 <= B <= 2048)
  /\ (L5.defined MV F B /\ L5.writable RSEGS MV F B /\ L5.writable RSEGS MV (F / 8 + 2147450880) (B / 8) /\ L5.u64_at RSEGS MV (F + B - 8) fl /\ L5.writable RSEGS MV fl 1)
  /\ (4096 <= fl /\ fl + 1 <= 2 ^ 47 /\ (2147446784 + 17592186048512 <= fl \/ fl + 1 <= 2147446784) /\ (F + B <= fl \/ fl + 1 <= F))
  /\ (L5.writable RSEGS MV spc (sp - spc) /\ own MV /\ F + B <= spc /\ fl + 1 <= spc /\ ahl_ceil ar + 4096 <= spc /\ sp <= 2 ^ 47)
  /\ (7036928 <= fb /\ fb + 2048 <= spc /\ fb mod 2048 = 0 /\ (2147446784 + 17592186048512 <= fb \/ fb + 2048 <= 2147446784))
  /\ (L5KA.zeros_at MV ((fb + 592) / 8 + 2147450880) 63 /\ L5.writable RSEGS MV (fb + 592) 504 /\ (forall a n0, fb + 592 <= a -> a + n0 <= fb + 1096 -> avis (ahid Aw1 model1) a n0))
  /\ (forall a n0, fb + 32 <= a -> a + n0 <= fb + 2040 -> 0 < n0 -> (a + n0 <= F \/ F + B <= a) /\ (a + n0 <= fl \/ fl + 1 <= a))
  /\ (avis (ahid Aw1 model1) (F / 8 + SB) (B / 8) /\ avis (ahid Aw1 model1) F B /\ avis (ahid Aw1 model1) spc (sp - spc)).
