(* [comment removed for export] *)
Lemma mk_fin M5 model5 LK5 Aw5 s5 sa5 sm5 e5 cr5 b5 (fx5 fx9 : FPState) R5 R9 (pc5 : Z) (M9v : mem) (t d : Z) :
  m_mem M5 model5 LK5 Aw5 s5 sa5 sm5 e5 cr5 b5 ->
  msteps RSEGS (st fx5 R5 pc5 (mrestrict (ahid Aw5 model5) M5)) (st fx9 R9 r M9v) ->
  mem_grows (mrestrict (ahid Aw5 model5) M5) M9v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ PMAUK.WretX F fl k (fun _ => False) a -> M9v (Z_to_bv 64 a) = mrestrict (ahid Aw5 model5) M5 (Z_to_bv 64 a)) ->
  L5.u8_at RSEGS M9v fl 0 ->
  regs_preserved R R9 ->
  ( (b5 = true /\ PQMA.p_more s5 = 0)
    \/ (b5 = b /\ PQRA.minv_d d s5 /\ (forall Mf, PNRNA.mprog_len t R9 Mf s s5 sa sa5 sm sm5) /\ PQRA.room_keep s s5 sm sm5) ) ->
  PMSP.credit_keep cr cr5 (pot_runA s sa) (pot_runA s5 sa5) ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PQMA.mpst) (st' : NEMA.aest)
          (sm' : PM.strm) (e' b' : bool) (cr' : credit),
      regs_preserved R R' ->
      PNRNA.gs_post_d RSEGS AD AQ AAD AE L ar d t R' M' fb s s' sa st' str sm sm' e e' b b' cat n ->
      L5CA.ahpres L ar LBX FF sp SCR (W_mrun fb) M M' ->
      PMSP.credit_keep cr cr' (pot_runA s sa) (pot_runA s' st') ->
      model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 pc5 M5 model5) K.
