Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Module PQASCA.

Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.
Abbreviation accA := PMSPA.accA.
Abbreviation kstr_at := (PQMA.kstr_at segs accA).
Abbreviation kcontent := (NEM.kcontent segs).
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation aobjA := PMSPA.aobjA.
Abbreviation ffrsA := PMSPA.ffrsA.
Abbreviation ffroomM := (PGSA.ffroomB PQRA.FCM).
Abbreviation pm_scr := PMSPA.pm_scr.
Abbreviation cfg := (@PMSP.cfg segs).
Abbreviation HV := (PMSPA.HV L ar).

(* [comment removed for export] *)
Definition pb_specCA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o c sp r SM g : Z) (x : PM.vstr) (bs : list Z),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r PQASA.PB_H -> ffroomM PQASA.PB_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 c -> 0 <= c < 256 -> aobjA FF o 24 -> o mod 8 = 0 ->
    kstr_at M o x -> kcontent M o x bs -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX -> PM.vs_size x < SM ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> kstr_at M' o x' -> kcontent M' o x' (bs ++ [c]) -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + 1 ->
        (PM.vs_size x < PM.vs_cap x -> PM.vs_own x' = PM.vs_own x /\ g' = g) ->
        L5CA.ahpres L ar LB FF sp (pm_scr PQASA.PB_H) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
Definition src_okCA (M : word -> option byte) (LB : list (Z * Z)) (FF : list fframe) (q n : Z) (sbs : list Z) : Prop :=
  PQASA.src_okA segs L HI M LB FF q n /\ Z.of_nat (length sbs) = n /\ L5.bytes_at segs M q sbs /\ NEM.bytes_ok sbs.

(* [comment removed for export] *)
Definition ins_specCA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o q n sp r SM g : Z) (x : PM.vstr) (bs sbs : list Z),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r PQASA.INS_H -> ffroomM PQASA.INS_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 o -> getr R 11%bv = Z_to_bv 64 (PM.vs_data o x + PM.vs_size x) ->
    getr R 12%bv = Z_to_bv 64 q -> getr R 13%bv = Z_to_bv 64 (q + n) -> getr R 14%bv = Z_to_bv 64 n ->
    0 <= n -> PM.vs_size x + n <= SM -> src_okCA M LB FF q n sbs -> (q + n <= o \/ o + 24 <= q) ->
    aobjA FF o 24 -> o mod 8 = 0 -> kstr_at M o x -> kcontent M o x bs -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> kstr_at M' o x' -> kcontent M' o x' (bs ++ sbs) -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + n ->
        (PM.vs_size x + n <= PM.vs_cap x -> PM.vs_own x' = PM.vs_own x /\ g' = g) ->
        L5CA.ahpres L ar LB FF sp (pm_scr PQASA.INS_H) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
