(* [comment removed for export] *)
Lemma sink_atA_agree P o k :
  0 <= o -> o + 24 <= 2 ^ 64 -> agA o 24 ->
  (0 < NESK.sk_c k -> 0 <= NESK.sk_b k /\ NESK.sk_b k + NESK.sk_c k <= 2 ^ 64 /\ agA (NESK.sk_b k) (NESK.sk_c k)) ->
