(* [comment removed for export] *)
Definition s_off (w : bool) : Z := if w then 24 else 48.
Definition s_SM (w : bool) : Z := if w then PQMA.SMK else PQMA.SMB.
Definition s_str (w : bool) (x : PQMA.ast) : PM.vstr := if w then PQMA.a_key x else PQMA.a_kb x.
Definition s_g (w : bool) (x : PQMA.ast) : Z := if w then PQMA.a_kg x else PQMA.a_kbg x.
Definition s_set (w : bool) (x : PQMA.ast) (y : PM.vstr) (g : Z) : PQMA.ast :=
  if w then PQMA.AST (PQMA.a_lv x) (PQMA.a_lb x) (PQMA.a_lk x) y g (PQMA.a_kb x) (PQMA.a_kbg x)
  else PQMA.AST (PQMA.a_lv x) (PQMA.a_lb x) (PQMA.a_lk x) (PQMA.a_key x) (PQMA.a_kg x) y g.
(* [comment removed for export] *)
Definition s_rest (w : bool) (x : PQMA.ast) : list (Z * Z) :=
  PQMA.lvec_own (PQMA.a_lb x) (PQMA.a_lk x) ++ PM.vs_own (if w then PQMA.a_kb x else PQMA.a_key x).
Lemma s_perm w x y g : Permutation (PM.vs_own y ++ s_rest w x) (PQMA.aown (s_set w x y g)).
