Lemma ck_sel2 (bl : Z) (p1 p2 q q' cr cr' : credit) :
  fst cr - fst q + fst q' <= fst cr' /\ snd cr - bl * snd q + bl * snd q' <= snd cr' ->
  (fst cr - (fst p1 + (fst p2 + fst q)) + (fst p1 + (fst p2 + fst q')) <= fst cr' /\ snd cr - bl * (snd p1 + (snd p2 + snd q)) + bl * (snd p1 + (snd p2 + snd q')) <= snd cr')
  /\ (fst cr - (fst p1 + (fst q + fst p2)) + (fst p1 + (fst q' + fst p2)) <= fst cr' /\ snd cr - bl * (snd p1 + (snd q + snd p2)) + bl * (snd p1 + (snd q' + snd p2)) <= snd cr').
Proof.
