(* [comment removed for export] *)
Lemma s_keep LB1 FFx spx scr (M1 M3 : mem) st1 :
  (forall f, In f FFx -> 0 <= ff_addr f /\ ff_addr f + ff_bytes (ff_class f) <= 2 ^ 47) -> (forall b, In b LB1 -> 0 <= fst b /\ fst b + snd b <= 2 ^ 47) ->
  L5SAR.ek L ar LB1 FFx spx scr [] M1 M3 -> incl (PQMA.aown st1) LB1 -> PMSPA.aobjA FFx oa PQMA.ASIZE -> PMSPA.aobjA FFx ov 8 ->
  adaptor_at M1 oa ov st1 /\ accA M1 oa PQMA.ASIZE /\ EVIS M1 ov /\ PMSTA.base_okA RSEGS AD M1 ->
  adaptor_at M3 oa ov st1 /\ accA M3 oa PQMA.ASIZE /\ EVIS M3 ov /\ PMSTA.base_okA RSEGS AD M3.
