(* [comment removed for export] *)
Definition scallee (pc hc : Z) (args : bvmap 5 word -> mem -> list (Z * Z) -> list fframe -> Z -> Z -> PM.vstr -> Z -> Prop) : Prop :=
  forall (fx : FPState) (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K0' : TSet)
         (LB : list (Z * Z)) (FF0 LK0 : list fframe) (Aw0 : list (Z * Z)) (cr0 : credit) (o sp0 r0 SM g d : Z) (x : PM.vstr),
    ri_inv HI (PM.vs_own x ++ LB) FF0 LK0 cr0 Aw0 M0 (vml_of model0) -> L5CA.amodel_ok Aw0 model0 -> K0' [] ->
    PMSPA.entryA AD L ar R0 M0 sp0 r0 hc -> PGSA.ffroomB PQRA.FCM hc FF0 LK0 -> PMSPA.ffrsA FF0 sp0 -> sp0 mod 16 = 0 ->
    args R0 M0 LB FF0 o SM x d -> PMSPA.aobjA FF0 o 24 -> o mod 8 = 0 -> kstr_at M0 o x -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) cr0 ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R0 R' -> kstr_at M' o x' -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + d ->
        L5CA.ahpres L ar LB FF0 sp0 (PMSPA.pm_scr hc) [(o, 24)] M0 M' ->
        PMSP.credit_keep cr0 cr' (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x' g')) ->
        model_rt model0 model' -> incl LK' LK0 -> incl Aw0 Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF0 LK' cr' Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r0 M' model') K0') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R0 pc M0 model0) K0'.

(* [comment removed for export] *)
Definition scalleeC (pc hc : Z) (args : bvmap 5 word -> mem -> list (Z * Z) -> list fframe -> Z -> Z -> PM.vstr -> Z -> list Z -> Prop) : Prop :=
  forall (fx : FPState) (R0 : bvmap 5 word) (M0 : mem) (model0 : Model) (K0' : TSet)
         (LB : list (Z * Z)) (FF0 LK0 : list fframe) (Aw0 : list (Z * Z)) (cr0 : credit) (o sp0 r0 SM g d : Z) (x : PM.vstr) (bs nb : list Z),
    ri_inv HI (PM.vs_own x ++ LB) FF0 LK0 cr0 Aw0 M0 (vml_of model0) -> L5CA.amodel_ok Aw0 model0 -> K0' [] ->
    PMSPA.entryA AD L ar R0 M0 sp0 r0 hc -> PGSA.ffroomB PQRA.FCM hc FF0 LK0 -> PMSPA.ffrsA FF0 sp0 -> sp0 mod 16 = 0 ->
    args R0 M0 LB FF0 o SM x d nb -> PMSPA.aobjA FF0 o 24 -> o mod 8 = 0 -> kstr_at M0 o x -> NEM.kcontent RSEGS M0 o x bs -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) cr0 ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R0 R' -> kstr_at M' o x' -> NEM.kcontent RSEGS M' o x' (bs ++ nb) -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + d ->
        L5CA.ahpres L ar LB FF0 sp0 (PMSPA.pm_scr hc) [(o, 24)] M0 M' ->
        PMSP.credit_keep cr0 cr' (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x' g')) ->
        model_rt model0 model' -> incl LK' LK0 -> incl Aw0 Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF0 LK' cr' Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r0 M' model') K0') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R0 pc M0 model0) K0'.

Local Notation "'GX' f" := (f L ar C HI LY HIok K R M model LBX FF LK Aw cr sp r PNVA.VIS_H (PQMA.aown sa ++ eso) WA HH AM K0 ENT FRM FRS Hh3 wappW) (at level 10, f at level 9, only parsing).

Section Frame.
Variables (spc olo ohi : Z) (ocell : Z -> Prop) (own : mem -> Prop) (k F fl : Z) (LK2 : list fframe) (M2 : mem) (model2 : Model).
Hypothesis G : PMAUK.gctx L ar HI LBX FF LK Aw sp (PMSPA.pm_scr PNVA.VIS_H) spc olo ohi ocell own F fl k LK2 M2 model2 cr (PQMA.aown sa ++ eso).
Hypothesis APART : forall a n0 sp0 scr0, (forall i, 0 <= i < n0 -> aclient L ar ((PQMA.aown sa ++ eso) ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n0 ->
         (a + n0 <= F \/ F + ff_bytes k <= a) /\ (a + n0 <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n0 <= fl \/ fl + 1 <= a).
Hypothesis HSPC : sp - 2048 <= spc /\ spc mod 16 = 0.
Local Notation B := (ff_bytes k).
Local Notation FF' := ((F, k, spc + 32) :: FF).
Local Notation GM := (PQAKR3.g_mem L ar HI M model LBX FF LK Aw sp PNVA.VIS_H WA spc own k F).
Local Notation "'GF' f" := (f L ar C HI LY HIok K R M model LBX FF LK Aw cr sp r PNVA.VIS_H (PQMA.aown sa ++ eso) WA HH AM K0 ENT FRM FRS Hh3 wappW spc olo ohi ocell own k F fl LK2 M2 model2 G APART HSPC) (at level 10, f at level 9, only parsing).

(* [comment removed for export] *)
Definition a_mem (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z)) (st1 : PQMA.ast) (eso1 : list (Z * Z)) (qe1 : credit) (cr1 : credit) : Prop :=
  GM (PQMA.aown st1 ++ eso1) M1 model1 LK1 Aw1 cr1
  /\ adaptor_at M1 oa ov st1 /\ accA M1 oa PQMA.ASIZE /\ PQMA.adaptor_ok st1 /\ EVIS M1 ov /\ PMSTA.base_okA RSEGS AD M1
  /\ PMSP.credit_keep cr cr1 (PM.credit_add (POT sa) QE) (PM.credit_add (POT st1) qe1) /\ (PMSP.credit_le (PM.credit_add (POT st1) qe1) cr1 /\ 0 <= fst qe1 /\ 0 <= snd qe1).   (* [comment removed for export] *)

