(* [comment removed for export] *)
Lemma s_lv M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 lv0 c :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 -> PQMA.a_lv st1 = lv0 ++ [c] ->
  let MV := mrestrict (ahid Aw1 model1) M1 in
  let e := PQMA.a_lb st1 + 24 * (Z.of_nat (length lv0) + 1) in
  L5.u64_at RSEGS MV (oa + 80) e
  /\ (4120 <= e /\ e <= 140737488355328 /\ e mod 8 = 0 /\ (2147446784 + 17592186048512 <= e - 24 \/ e - 24 + 24 <= 2147446784) /\ e <= spc)
  /\ (L5KA.zeros_at MV ((e - 24) / 8 + 2147450880) 1 /\ L5KA.zeros_at MV ((e - 20) / 8 + 2147450880) 1
      /\ L5KA.zeros_at MV ((e - 16) / 8 + 2147450880) 1 /\ L5KA.zeros_at MV ((e - 8) / 8 + 2147450880) 1)
  /\ (L5.u32_at RSEGS MV (e - 24) (PQMA.lv_t c) /\ L5.u32_at RSEGS MV (e - 20) (PQMA.lv_k c) /\ L5.u32_at RSEGS MV (e - 16) (PQMA.lv_eo c))
  /\ (L5.defined MV (e - 24) 24 /\ L5.writable RSEGS MV (e - 24) 24 /\ avis (ahid Aw1 model1) (e - 24) 24)
  /\ ((e <= oa \/ oa + 96 <= e - 24) /\ (e <= F \/ F + B <= e - 24) /\ (e <= ov \/ ov + 8 <= e - 24))
  /\ (PQMA.alvl_ok c /\ (PQMA.lv_t c = 1 -> PQMA.lv_k c <> 0))
  /\ In (PQMA.a_lb st1, 24 * 2 ^ PQMA.a_lk st1) (PQMA.aown st1) /\ e <= PQMA.a_lb st1 + 24 * 2 ^ PQMA.a_lk st1.
Proof using All.
