Lemma s_own_neq M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  (forall q m, In (q, m) (PM.vs_own (PQMA.a_key st1)) -> PQMA.a_lb st1 <> q)
  /\ (forall q m, In (q, m) (PM.vs_own (PQMA.a_kb st1)) -> PQMA.a_lb st1 <> q)
  /\ (forall q m q' m', In (q, m) (PM.vs_own (PQMA.a_key st1)) -> In (q', m') (PM.vs_own (PQMA.a_kb st1)) -> q <> q').
