(* [comment removed for export] *)
Lemma s_fin M5 model5 LK5 Aw5 st5 eso5 qe5 cr5 (fx5 fx9 : FPState) R5 R9 (pc5 : Z) (M9v : mem) :
  a_mem M5 model5 LK5 Aw5 st5 eso5 qe5 cr5 ->
  msteps RSEGS (st fx5 R5 pc5 (mrestrict (ahid Aw5 model5) M5)) (st fx9 R9 r M9v) ->
  mem_grows (mrestrict (ahid Aw5 model5) M5) M9v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ PMAUK.WretX F fl k (fun _ => False) a -> M9v (Z_to_bv 64 a) = mrestrict (ahid Aw5 model5) M5 (Z_to_bv 64 a)) ->
  L5.u8_at RSEGS M9v fl 0 ->
  (forall (Mf : mem) (modelf : Model),
      adaptor_at Mf oa ov st5 -> PQMA.adaptor_ok st5 ->
      L5CA.ahpres L ar LBX FF sp SCR WA M Mf ->
      PMSP.credit_keep cr cr5 (PM.credit_add (POT sa) QE) (PM.credit_add (POT st5) qe5) ->
      model_rt model modelf -> incl LK5 LK -> incl Aw Aw5 -> L5CA.amodel_ok Aw5 modelf ->
      ri_inv HI ((PQMA.aown st5 ++ eso5) ++ LBX) FF LK5 cr5 Aw5 Mf (vml_of modelf) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx9 R9 r Mf modelf) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 pc5 M5 model5) K.
Proof using All.
