(* [comment removed for export] *)
Lemma s_call_s (w : bool) M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (fx1 : FPState) R1 (pc ra hc d : Z)
      (args : bvmap 5 word -> mem -> list (Z * Z) -> list fframe -> Z -> Z -> PM.vstr -> Z -> Prop) :
  scallee pc hc args -> 0 <= hc -> hc + 1 <= PNVA.VIS_H ->
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  args R1 M1 ((s_rest w st1 ++ eso1) ++ LBX) FF' (oa + s_off w) (s_SM w) (s_str w st1) d ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 x' g' cr3,
      regs_preserved R1 R2 ->
      a_mem M3 model3 LK3 Aw3 (s_set w st1 x' g') eso1 qe1 cr3 ->
      PM.vs_size x' = PM.vs_size (s_str w st1) + d ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      (forall a, F / 8 + SB <= a < F / 8 + SB + B / 8 -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc M1 model1) K.
Proof using All.
