(* [comment removed for export] *)
Lemma s_piece_w M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 st3 (fx1 fx2 : FPState) R1 R2 (pc1 pc2 : Z) (M2v : mem) (Wp : Z -> Prop) (Wl : list L5.range) :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pc2 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M2v (Z_to_bv 64 a) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 a)) ->
  (forall a, Wp a -> ~ ocell a /\ ((spc <= a < sp) \/ (F <= a < F + B - 8 /\ ~ (F + 24 <= a < F + 32)) \/ (F / 8 + SB <= a < F / 8 + SB + B / 8)
                                  \/ ((oa + 24 <= a < oa + 96 \/ in_block (PQMA.aown st1 ++ eso1) a) /\ ~ L5.outside Wl a))) ->
  PMKA.wapp Wl ->
  (forall rr a, In rr Wl -> L5.in_rng rr a -> ~ (ov <= a < ov + 8) /\ ~ (oa <= a < oa + 24) /\ ~ (65536 <= a < 7036928)) ->
  PQMA.aown st3 = PQMA.aown st1 -> PQMA.adaptor_ok st3 -> PQMA.pot_adaptor (PMSPA.HV L ar) st3 = PQMA.pot_adaptor (PMSPA.HV L ar) st1 ->
  (forall (M3 : mem) model3,
      L5SAR.ek L ar ((PQMA.aown st1 ++ eso1) ++ LBX) FF sp SCR Wl M1 M3 -> mem_grows M1 M3 -> mrestrict (ahid Aw1 model1) M3 = M2v ->
      ri_inv HI ((PQMA.aown st1 ++ eso1) ++ LBX) FF' LK1 cr1 Aw1 M3 (vml_of model3) ->
      adaptor_at M3 oa ov st3) ->
  (forall (M3 : mem) model3,
      a_mem M3 model3 LK1 Aw1 st3 eso1 qe1 cr1 ->
      ahid Aw1 model3 = ahid Aw1 model1 -> mrestrict (ahid Aw1 model1) M3 = M2v ->
      (forall a, 0 <= a < 2 ^ 64 -> ~ Wp a -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> mem_grows M1 M3 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M3 model3) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc1 M1 model1) K.
