(* [comment removed for export] *)
Lemma s_kclr M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 (fx1 fx2 : FPState) R1 R2 (pc1 pc2 : Z) (M2v : mem) :
  a_mem M1 model1 LK1 Aw1 st1 eso1 qe1 cr1 ->
  msteps RSEGS (st fx1 R1 pc1 (mrestrict (ahid Aw1 model1) M1)) (st fx2 R2 pc2 M2v) ->
  mem_grows (mrestrict (ahid Aw1 model1) M1) M2v ->
  match PQMA.a_key st1 with
  | PM.VShort n => (forall i, 0 <= i < 2 ^ 64 -> ~ (oa + 24 <= i < oa + 24 + 2) -> M2v (Z_to_bv 64 i) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 i))
                   /\ L5.u8_at RSEGS M2v (oa + 24) 0
  | PM.VLong c n p => (forall i, 0 <= i < 2 ^ 64 -> ~ (oa + 32 <= i < oa + 32 + 8) -> ~ (p + 0 <= i < p + 0 + 1) -> M2v (Z_to_bv 64 i) = mrestrict (ahid Aw1 model1) M1 (Z_to_bv 64 i))
                      /\ L5.u64_at RSEGS M2v (oa + 32) 0
  end ->
  (forall (M3 : mem) model3,
      a_mem M3 model3 LK1 Aw1 (s_set true st1 (kclr (PQMA.a_key st1)) (PQMA.a_kg st1)) eso1 qe1 cr1 ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 pc2 M3 model3) K) ->
