Module PQASCA2.

Section Specs.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.
Abbreviation accA := PMSPA.accA.
Abbreviation kstr_at := (PQMA.kstr_at segs accA).
Abbreviation kcontent := (NEM.kcontent segs).
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation aobjA := PMSPA.aobjA.
Abbreviation ffrsA := PMSPA.ffrsA.
Abbreviation ffroomM := (PGSA.ffroomB PQRA.FCM).
Abbreviation pm_scr := PMSPA.pm_scr.
Abbreviation cfg := (@PMSP.cfg segs).
Abbreviation HV := (PMSPA.HV L ar).

(* [comment removed for export] *)
Definition from_specCA (pc : Z) (d : Z -> Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o v sp r SM g : Z) (x : PM.vstr) (bs : list Z),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r PQASA.FROM_H -> ffroomM PQASA.FROM_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 v -> 0 <= v < 2 ^ 64 -> getr R 11%bv = Z_to_bv 64 o -> aobjA FF o 24 -> o mod 8 = 0 ->
    kstr_at M o x -> kcontent M o x bs -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX -> PM.vs_size x + 20 <= SM ->
    PMSTA.base_okA segs A M ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit)
            (ds : list Z),
        regs_preserved R R' -> kstr_at M' o x' -> kcontent M' o x' (bs ++ ds) -> NEM.ascii ds -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + d v ->
        L5CA.ahpres L ar LB FF sp (pm_scr PQASA.FROM_H) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
Definition fromu_specCA (pc : Z) : Prop := from_specCA pc PQVA.ndig.
Definition fromi_specCA (pc : Z) : Prop := from_specCA pc PQASA.nchars.

(* [comment removed for export] *)
Lemma from_specCA_free pc d : from_specCA pc d -> (forall M o x, kstr_at M o x -> exists bs, kcontent M o x bs) -> PQASA.from_specA segs A L ar HI pc d.
Proof.
  intros FR KC fx R M model K LB FF LK Aw cr o v sp r SM g x HH AM K0 ENT FRM FRS SP16 A10 Hv A11 AO O8 KS KO HSM ROOM BASE CR KONT.
  destruct (KC M o x KS) as (bs & KCb).
  apply (FR fx R M model K LB FF LK Aw cr o v sp r SM g x bs HH AM K0 ENT FRM FRS SP16 A10 Hv A11 AO O8 KS KCb KO HSM ROOM BASE CR).
  intros fx' R' M' model' LK' Aw' x' g' cr' ds RP KS' _ _ KO' SZ' HP CK MRT IL IA AM' HH'.
  exact (KONT fx' R' M' model' LK' Aw' x' g' cr' RP KS' KO' SZ' HP CK MRT IL IA AM' HH').
Qed.
End Specs.
End PQASCA2.

