Definition from_args (v dv : Z) (R0 : bvmap 5 word) (M0 : mem) (LB : list (Z * Z)) (FF0 : list fframe) (o SM : Z) (x : PM.vstr) (d : Z) : Prop :=
  getr R0 (reg 10) = Z_to_bv 64 v /\ 0 <= v < 2 ^ 64 /\ getr R0 (reg 11) = Z_to_bv 64 o /\ PM.vs_size x + 20 <= SM /\ PMSTA.base_okA RSEGS AD M0 /\ d = dv.
Lemma from_sc pc (df : Z -> Z) v : PQASA.from_specA RSEGS AD L ar HI pc df -> PQAKS3.scallee L ar HI pc PQASA.FROM_H (from_args v (df v)).
Proof.
  intros FR fx R0 M0 model0 K0' LB FF0 LK0 Aw0 cr0 o sp0 r0 SM g d x HH0 AM0 K00 ENT0 FRM0 FRS0 SP0 (A10 & Hv & A11 & Hsz & BASE0 & ->) AOo O8o KS KOK SMx CL KONT.
  rewrite <- L5K.rl10 in A10. rewrite <- L5K.rl11 in A11.
  exact (FR fx R0 M0 model0 K0' LB FF0 LK0 Aw0 cr0 o v sp0 r0 SM g x HH0 AM0 K00 ENT0 FRM0 FRS0 SP0 A10 Hv A11 AOo O8o KS KOK SMx Hsz BASE0 CL KONT).
Qed.
End WithHeap.
(* [comment removed for export] *)
Lemma ndig_f_rng f v : 1 <= PQVA.ndig_f f v <= Z.of_nat f + 1.
Proof.
  revert v. induction f as [|f IH]; intros v; cbn [PQVA.ndig_f]; [lia|]. destruct (Z.ltb v 10); [lia|]. specialize (IH (v / 10)). lia.
Qed.
Lemma ndig_f_lt f : forall v, 0 <= v < 10 ^ Z.of_nat f -> PQVA.ndig_f f v <= Z.max 1 (Z.of_nat f).
Proof.
  induction f as [|f IH]; intros v Hv; cbn [PQVA.ndig_f]; [lia|]. destruct (Z.ltb_spec v 10) as [X|X]; [lia|].
  assert (E : 10 ^ Z.of_nat (Datatypes.S f) = 10 * 10 ^ Z.of_nat f) by (rewrite Nat2Z.inj_succ, Z.pow_succ_r by lia; reflexivity).
  rewrite E in Hv. assert (Hq : 0 <= v / 10 < 10 ^ Z.of_nat f) by (split; [apply Z.div_pos; lia| apply Z.div_lt_upper_bound; lia]).
  specialize (IH (v / 10) Hq). destruct f as [|f'].
  - exfalso. assert (Q1 : v / 10 < 1) by exact (proj2 Hq). assert (Q0 : 0 <= v / 10) by exact (proj1 Hq). clear Hq IH Hv E.
    pose proof (Z.div_mod v 10 ltac:(lia)) as D. pose proof (Z.mod_pos_bound v 10 ltac:(lia)) as B. lia.
  - rewrite !Nat2Z.inj_succ in *. lia.
Qed.
Lemma ndig_rng v : 0 <= v < 2 ^ 64 -> 1 <= PQVA.ndig v <= 20.
Proof.
  intros Hv. unfold PQVA.ndig. split; [apply (ndig_f_rng 20 v)|].
  assert (B : 0 <= v < 10 ^ Z.of_nat 20) by (split; [exact (proj1 Hv)| eapply Z.lt_trans; [exact (proj2 Hv)| vm_compute; reflexivity]]).
  pose proof (ndig_f_lt 20 v B) as X. change (Z.max 1 (Z.of_nat 20)) with 20 in X. exact X.
Qed.
End PQAKF3.

