Lemma ffroomN_const h FF LK : PGSA.ffroomB PQRA.FCM h FF LK <-> ffroomN (fun _ => h) FF LK.
Proof. unfold PGSA.ffroomB, ffroomN. split; intros H k Hk; apply (H k Hk). Qed.
Lemma ffroomN_le need h FF LK : ffroomN need FF LK -> (forall k, In k PQRA.FCM -> h <= need k) -> PGSA.ffroomB PQRA.FCM h FF LK.
Proof. intros H Hle k Hk. specialize (H k Hk). specialize (Hle k Hk). lia. Qed.
Lemma ffroomN_mono need need' FF LK : ffroomN need FF LK -> (forall k, In k PQRA.FCM -> need' k <= need k) -> ffroomN need' FF LK.
Proof. intros H Hle k Hk. specialize (H k Hk). specialize (Hle k Hk). lia. Qed.

