Definition entryAs (R : bvmap 5 word) (M : mem) (sp r scr : Z) : Prop :=
  getr R 1%bv = Z_to_bv 64 r /\ L5.ra_ok r /\ getr R 2%bv = Z_to_bv 64 sp /\ getr R 3%bv = Z_to_bv 64 (pa_gp A)
  /\ getr R 4%bv = Z_to_bv 64 (hl_tp L) /\ L5CA.astk ar M sp scr /\ shadow_zero M (sp - scr) (scr / 8).
Lemma entryAs_of_entryA R M sp r h : PMSPA.entryA A L ar R M sp r h <-> entryAs R M sp r (PMSPA.pm_scr h).
Proof. unfold PMSPA.entryA, entryAs. tauto. Qed.

