Definition snprintf_runA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : mem) (sp ra buf prec d : Z),
    getr R 2%bv = Z_to_bv 64 sp -> getr R 1%bv = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R 4%bv = Z_to_bv 64 (hl_tp L) ->
    getr R 10%bv = Z_to_bv 64 buf -> getr R 11%bv = Z_to_bv 64 WDL.SNP_BUF -> getr R 12%bv = Z_to_bv 64 FMT_G_A ->
    getr R 13%bv = Z_to_bv 64 prec -> getr R 14%bv = Z_to_bv 64 d -> (prec = 15 \/ prec = 17) -> WDL.dbl_nz d ->
    IMG_HI_A + SNPI_SCR <= sp -> BIGSHADOW_HI + SNPI_SCR <= sp -> sp <= 2 ^ 47 -> sp mod 16 = 0 -> bigapart (sp - SNPI_SCR) SNPI_SCR ->
    L5.writable segs M (sp - SNPI_SCR) SNPI_SCR -> L5.defined M (sp - SNPI_SCR) SNPI_SCR -> shadow_zero M (sp - SNPI_SCR) (SNPI_SCR / 8) ->
    IMG_HI_A <= buf -> buf + WDL.SNP_BUF <= 2 ^ 47 -> buf mod 64 = 32 -> bigapart buf WDL.SNP_BUF -> (sp <= buf \/ buf + WDL.SNP_BUF <= sp - SNPI_SCR) ->
    L5.writable segs M buf WDL.SNP_BUF -> L5.defined M buf WDL.SNP_BUF ->
    L5.u64_at segs M (buf / 8 + SB - 4) LRZ_QWORD -> L5KA.zeros_at M (buf / 8 + SB) 4 ->
    L5.img_clear M 0x10000 0x158000 -> snp_cellsM M -> fmt_shadowM M -> img_shadowM M ->
    exists (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (n : Z) (bs : list Z),
      mem_grows M M'
      /\ (forall a : word, ~ (sp - SNPI_SCR <= bv_unsigned a < sp) -> ~ (buf <= bv_unsigned a < buf + WDL.SNP_BUF) -> M' a = M a)
      /\ (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (sp - SNPI_SCR <= i < sp) -> ~ (buf <= i < buf + WDL.SNP_BUF) -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
      /\ msteps segs (st fx R pc M) (st fx' R' ra M')
      /\ (forall x, In x LIBC_CS -> getr R' (reg x) = getr R (reg x))
      /\ getr R' 10%bv = Z_to_bv 64 n /\ 1 <= n <= WDL.SNP_MAX /\ Z.of_nat (length bs) = n
      /\ (WDL.gnum bs = true \/ WDL.gspecial bs) /\ Forall (fun c => 0 <= c < 256) bs /\ L5.bytes_at segs M' buf (bs ++ [0])
      /\ L5.defined M' (sp - SNPI_SCR) SNPI_SCR.

Definition strtod_runA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : mem) (sp ra tp s endp n : Z) (bs : list Z),
    getr R 2%bv = Z_to_bv 64 sp -> getr R 1%bv = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R 4%bv = Z_to_bv 64 tp -> tp = pa_tp A ->
    getr R 10%bv = Z_to_bv 64 s -> getr R 11%bv = Z_to_bv 64 endp ->
    Z.of_nat (length bs) = n -> 1 <= n <= WDL.SNP_MAX -> (WDL.gnum bs = true \/ WDL.gspecial bs) -> Forall (fun c => 0 <= c < 256) bs ->
    L5.bytes_at segs M s (bs ++ [0]) -> frm_zero (@fp_csr fx) ->
    IMG_HI_A + STRTOD_SCR <= sp -> sp <= 2 ^ 47 -> sp mod 16 = 0 -> bigapart (sp - STRTOD_SCR) STRTOD_SCR ->
    L5.writable segs M (sp - STRTOD_SCR) STRTOD_SCR -> L5.defined M (sp - STRTOD_SCR) STRTOD_SCR ->
    IMG_HI_A <= s -> s + n + 1 <= 2 ^ 47 -> bigapart s (n + 1) -> (sp <= s \/ s + n + 1 <= sp - STRTOD_SCR) ->
    IMG_HI_A <= endp -> endp + 8 <= 2 ^ 47 -> bigapart endp 8 -> (sp <= endp \/ endp + 8 <= sp - STRTOD_SCR) -> (endp + 8 <= s \/ s + n + 1 <= endp) ->
    L5.writable segs M endp 8 -> L5.defined M endp 8 ->
    L5.writable segs M (tp - ERRNO_OFF) 4 ->
    L5.img_clear M 0x10000 0x158000 ->
    exists (fx' : FPState) (R' : bvmap 5 word) (M' : mem),
      mem_grows M M'
      /\ (forall a : word, ~ (sp - STRTOD_SCR <= bv_unsigned a < sp) -> ~ (endp <= bv_unsigned a < endp + 8) ->
                           ~ (tp - ERRNO_OFF <= bv_unsigned a < tp - ERRNO_OFF + 4) -> M' a = M a)
      /\ (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (sp - STRTOD_SCR <= i < sp) -> ~ (endp <= i < endp + 8) ->
                         ~ (tp - ERRNO_OFF <= i < tp - ERRNO_OFF + 4) -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
      /\ msteps segs (st fx R pc M) (st fx' R' ra M')
      /\ (forall x, In x LIBC_CS -> getr R' (reg x) = getr R (reg x))
      /\ L5.u64_at segs M' endp (s + n) /\ L5.bytes_at segs M' s (bs ++ [0])
      /\ L5.defined M' (sp - STRTOD_SCR) STRTOD_SCR /\ frm_zero (@fp_csr fx').

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition pusherA (pc scr : Z) (need : Z -> Z) (W : list L5.range) (mx : Z)
           (pre : bvmap 5 word -> mem -> list fframe -> Z -> Z -> Z -> Prop) (post : bvmap 5 word -> Prop) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (so os sp r SM g : Z) (x : PM.vstr),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryAs R M sp r scr -> ffroomN need FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    pre R M FF so os sp ->
    rcellA M sp so 8 -> so mod 8 = 0 -> L5.u64_at segs M so os -> (so + 8 <= os \/ os + 24 <= so) ->
    aobjA FF os 24 -> os mod 8 = 0 -> kstr_at M os x -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX -> PM.vs_size x + mx <= SM ->
    PMSTA.base_okA segs A M ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> post R' -> kstr_at M' os x' -> PQMA.ks_ok SM x' g' ->
        PM.vs_size x <= PM.vs_size x' <= PM.vs_size x + mx ->
        L5CA.ahpres L ar LB FF sp scr ((os, 24) :: W) M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
Definition fe_specA (pc : Z) : Prop :=
  pusherA pc FE_SCR N1 [] FE_MAX
    (fun R _ _ so _ _ => exists k, getr R 10%bv = Z_to_bv 64 k /\ -999 <= k <= 999 /\ getr R 11%bv = Z_to_bv 64 so)
    (fun _ => True).

(* [comment removed for export] *)
Definition pr_specA (pc : Z) : Prop :=
  pusherA pc PR_SCR N1 [] PR_MAX
    (fun R M FF so os sp => exists buf len k, getr R 10%bv = Z_to_bv 64 buf /\ getr R 11%bv = Z_to_bv 64 len /\ getr R 12%bv = Z_to_bv 64 k
        /\ getr R 13%bv = Z_to_bv 64 (-4) /\ getr R 14%bv = Z_to_bv 64 17 /\ getr R 15%bv = Z_to_bv 64 so
        /\ 1 <= len <= 21 /\ -400 <= k <= 400 /\ rbufA M FF buf G_BUF os)
    (fun _ => True).

(* [comment removed for export] *)
Definition db_specA (pc : Z) : Prop :=
  pusherA pc DB_SCR N1 [] DB_MAX
    (fun R M FF so os sp => exists buf n dp, getr R 10%bv = Z_to_bv 64 buf /\ getr R 11%bv = Z_to_bv 64 n /\ getr R 12%bv = Z_to_bv 64 dp /\ getr R 13%bv = Z_to_bv 64 so
        /\ 0 <= n <= WDL.SNP_MAX /\ 0 <= dp < 256 /\ rbufA M FF buf n os)
    (fun _ => True).

(* [comment removed for export] *)
Definition dgf_specA (pc : Z) : Prop :=
  pusherA pc DGF_SCR DGF_N (ERRNO_W (pa_tp A)) DG_MAX
    (fun R _ _ so _ _ => exists dp, getr R 10%bv = Z_to_bv 64 dp /\ 0 <= dp < 256 /\ getr R 11%bv = Z_to_bv 64 so)
    (fun R' => getr R' 10%bv = Z_to_bv 64 1).

(* [comment removed for export] *)
Definition dgt_specA (pc : Z) : Prop :=
  pusherA pc DGT_SCR DGT_N (ERRNO_W (pa_tp A)) DG_MAX
    (fun R _ _ so _ _ => exists dp, getr R 10%bv = Z_to_bv 64 dp /\ 0 <= dp < 256 /\ getr R 11%bv = Z_to_bv 64 so)
    (fun R' => getr R' 10%bv = Z_to_bv 64 1).

(* [comment removed for export] *)
Definition wd_atA (M : mem) (o : Z) : Prop := L5.u8_at segs M o 0 /\ L5.u32_at segs M (o + 4) 0 /\ L5.defined M o 12.
(* [comment removed for export] *)
Definition wd_specA (pc : Z) : Prop :=
  pusherA pc WD_SCR WD_N (ERRNO_W (pa_tp A)) WD.WD_MAX
    (fun R M _ so os sp => exists o, getr R 10%bv = Z_to_bv 64 o /\ getr R 11%bv = Z_to_bv 64 so /\ rcellA M sp o 12 /\ wd_atA M o
        /\ (o + 12 <= os \/ os + 24 <= o))
    (fun _ => True).

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition ds_specA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (s n valp sp r : Z) (bs : list Z),
    ri_inv HI LB FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryAs R M sp r DS_SCR -> ffroomN DS_N FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 s -> getr R 11%bv = Z_to_bv 64 n -> getr R 12%bv = Z_to_bv 64 valp ->
    Z.of_nat (length bs) = n -> 1 <= n <= WDL.SNP_MAX -> (WDL.gnum bs = true \/ WDL.gspecial bs) -> Forall (fun c => 0 <= c < 256) bs ->
    L5.bytes_at segs M s (bs ++ [0]) -> aobjA FF s (n + 1) -> L5.defined M s (n + 1) ->
    rcellA M sp valp 8 -> valp mod 8 = 0 -> (valp + 8 <= s \/ s + n + 1 <= valp) ->
    PMSTA.base_okA segs A M ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (ec : Z),
        regs_preserved R R' -> getr R' 11%bv = Z_to_bv 64 ec -> (ec = 0 \/ ec = 34) ->
        L5.bytes_at segs M' s (bs ++ [0]) -> L5.defined M' valp 8 ->
        L5CA.ahpres L ar LB FF sp DS_SCR ((valp, 8) :: ERRNO_W (pa_tp A)) M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI LB FF LK' cr Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition snp_cells (C : asan_statics_cells) : Prop :=
  In (0x160758, 1, 1) (asc_cells C) /\ In (0x1f15fc, 1, 1) (asc_cells C) /\ In (0x158c30, 8, 0x14686c) (asc_cells C) /\ In (0x158be8, 8, 0x13b8b8) (asc_cells C)
  /\ In (0x160759, 1, 1) (asc_cells C) /\ In (0x158da8, 8, 0x14916c) (asc_cells C) /\ In (0x158da0, 8, 0x148d68) (asc_cells C) /\ In (0x158c28, 8, 0x14056c) (asc_cells C)
  /\ In (0x160760, 8, 0x7fffffffffff) (asc_cells C) /\ In (0x160768, 8, 0) (asc_cells C) /\ In (0x160770, 8, 0) (asc_cells C).
Definition snp_rt : Prop :=
  forall LB FF LK cr Aw M V, ri_inv HI LB FF LK cr Aw M V -> snp_cellsM M /\ fmt_shadowM M.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition wd_okA_stmt (pb_pc sn_pc st_pc g3_pc wd_pc : Z) : Prop :=
  PQASA.pb_specA segs A L ar HI pb_pc -> snprintf_runA sn_pc -> strtod_runA st_pc -> grisu3_runA g3_pc -> wd_specA wd_pc.

Variable AQ : pq_addrs.
Abbreviation annA := PQRA.annA.
Abbreviation adaptor_at := (PQMA.adaptor_at segs A accA annA (qa_vp_adaptor AQ)).
Definition vis_specW (pc : Z) (W : Z -> list L5.range)
           (args : bvmap 5 word -> mem -> list fframe -> list (Z * Z) -> Z -> Prop)
           (pre : bvmap 5 word -> mem -> PQMA.ast -> Prop)
           (step : bvmap 5 word -> mem -> PQMA.ast -> PQMA.ast -> Prop) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (sp r oa ov : Z) (st : PQMA.ast),
    ri_inv HI (PQMA.aown st ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r PQVA.VIS_H -> PGSA.ffroomB PQRA.FCM PQVA.VIS_H FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 oa -> args R M FF LBX oa ->
    aobjA FF oa PQMA.ASIZE -> oa mod 8 = 0 -> aobjA FF ov 8 -> ov mod 8 = 0 -> (oa + PQMA.ASIZE <= ov \/ ov + 8 <= oa) ->
    adaptor_at M oa ov st -> accA M oa PQMA.ASIZE -> PQMA.adaptor_ok st -> PMSPA.visitor_at segs A M ov -> pre R M st ->
    PMSTA.base_okA segs A M -> PMSP.credit_le (PMSPA.scA L (PQMA.pot_adaptor HV st)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (st' : PQMA.ast) (cr' : credit),
        regs_preserved R R' ->
        adaptor_at M' oa ov st' -> PQMA.adaptor_ok st' -> step R M st st' ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr PQVA.VIS_H) (W oa) M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_adaptor HV st)) (PMSPA.scA L (PQMA.pot_adaptor HV st')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (PQMA.aown st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
Definition v_double_specE : Prop :=
  vis_specW (qa_v_double AQ) (PQMA.adaptor_W A) PQVA.no_args (PQVA.pre_val PQVA.d_double) (fun _ _ => PQVA.step_val PQVA.d_double).

(* [comment removed for export] *)
Lemma vis_specW_std pc args pre step :
  vis_specW pc (PQMA.adaptor_W A) args pre step <-> PQVA.vis_spec segs A AQ L ar HI pc args pre step.
Proof. unfold vis_specW, PQVA.vis_spec. split; intros H; exact H. Qed.
(* [comment removed for export] *)
Lemma v_double_specE_eq : v_double_specE <-> PQVA.v_double_spec segs A AQ L ar HI.
Proof. unfold v_double_specE, PQVA.v_double_spec. apply vis_specW_std. Qed.

