Variable PBPC : Z.
Hypothesis PB : PQASA.pb_specA RSEGS AD L ar HI PBPC.
Abbreviation HV := (PMSPA.HV L ar).

(* [comment removed for export] *)
Lemma zsh_vis LB FF LK cr Aw (M : mem) model p n g :
  ri_inv HI LB FF LK cr Aw M (vml_of model) -> 0 <= ahl_ceil ar -> ahl_ceil ar <= p -> p + n <= ar_sptop ar -> ar_sptop ar <= 2 ^ 47 -> p mod 8 = 0 -> 0 <= g -> 8 * g <= n + 7 ->
  VA.zsh M p n -> L5KA.zeros_at (mrestrict (ahid Aw model) M) (p / 8 + 2147450880) g.
