(* [comment removed for export] *)
Section Push.
Variables (K : TSet) (R : bvmap 5 word) (M : mem) (model : Model) (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit)
          (so os sp r SM g : Z) (x0 : PM.vstr) (SCR : Z) (need : Z -> Z) (W : list L5.range) (MAX : Z) (post : bvmap 5 word -> Prop).
Hypothesis HH : ri_inv HI (PM.vs_own x0 ++ LB) FF LK cr Aw M (vml_of model).
Hypothesis AM : L5CA.amodel_ok Aw model.
Hypothesis K0 : K [].
Hypothesis ENT : VA.entryAs AD L ar R M sp r SCR.
Hypothesis FRM : VA.ffroomN need FF LK.
Hypothesis FRS : PMSPA.ffrsA FF sp.
Hypothesis RSO : VA.rcellA ar M sp so 8.
Hypothesis SO8 : so mod 8 = 0.
Hypothesis CSO : L5.u64_at RSEGS M so os.
Hypothesis AOS : PMSPA.aobjA FF os 24.
Hypothesis OS8 : os mod 8 = 0.
Hypothesis KS0 : kstr_at M os x0.
Hypothesis KOK0 : PQMA.ks_ok SM x0 g.
Hypothesis SMX : SM <= PQASA.SMMAX.
Hypothesis SZ0 : PM.vs_size x0 + MAX <= SM.
Hypothesis BASE : PMSTA.base_okA RSEGS AD M.
Hypothesis CR0 : PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x0 g)) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
    regs_preserved R R' -> post R' -> kstr_at M' os x' -> PQMA.ks_ok SM x' g' ->
    PM.vs_size x0 <= PM.vs_size x' <= PM.vs_size x0 + MAX ->
    L5CA.ahpres L ar LB FF sp SCR ((os, 24) :: W) M M' ->
    PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x0 g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
    model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
    ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
    srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K.
(* [comment removed for export] *)
Hypothesis WIMG : forall rr, In rr W -> 0 <= fst rr /\ fst rr + snd rr <= 7036928.
Hypothesis HSCR16 : SCR mod 16 = 0.
Variables (FR : Z) (ocell : Z -> Prop) (own : mem -> Prop).
Hypothesis HFR : 0 <= FR /\ FR mod 16 = 0.
Hypothesis HSCR : VA.PB_SCR + FR <= SCR.
Hypothesis GOCR : forall a, ocell a -> sp - FR <= a < sp.
Hypothesis GOWN : forall M1 M1' : mem, own M1 -> (forall a, ocell a -> M1' (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) -> own M1'.
Hypothesis NEED1 : forall k, In k PQRA.FCM -> 1 <= need k.
Local Notation spc := (sp - FR).
Local Notation WT := ((os, 24) :: W).
Local Notation POT0 := (PMSPA.scA L (PQMA.pot_ks HV SM x0 g)).

(* [comment removed for export] *)
Definition inv (own' : mem -> Prop) (n : Z) (M1 : mem) (model1 : Model) (LK1 : list fframe) (Aw1 : list (Z * Z)) (x : PM.vstr) (g1 : Z) (cr1 : credit) : Prop :=
  ri_inv HI (PM.vs_own x ++ LB) FF LK1 cr1 Aw1 M1 (vml_of model1) /\ L5CA.amodel_ok Aw1 model1 /\ model_rt model model1 /\ incl Aw Aw1 /\ incl LK1 LK /\
  L5CA.astk ar M1 sp SCR /\ ek L ar LB FF sp SCR WT M M1 /\ dk L ar LB FF sp SCR M M1 /\ own' M1 /\
  kstr_at M1 os x /\ PQMA.ks_ok SM x g1 /\ PM.vs_size x = PM.vs_size x0 + n /\
  PMSTA.base_okA RSEGS AD M1 /\
  PMSP.credit_keep cr cr1 POT0 (PMSPA.scA L (PQMA.pot_ks HV SM x g1)).

(* [comment removed for export] *)
Lemma ctx :
  (ahl_ceil ar + 4096 + SCR <= sp /\ sp <= ar_sptop ar /\ 140735340871680 <= ar_sptop ar <= 2 ^ 47 /\ sp mod 16 = 0 /\ 0 <= r < 2 ^ 47 /\ r mod 2 = 0)
  /\ (7036928 <= os /\ os + 24 <= ahl_ceil ar /\ (2147446784 + 17592186048512 <= os \/ os + 24 <= 2147446784))
  /\ (sp <= so /\ so + 8 <= ar_sptop ar)
