Lemma pb_entry own' n M1 model1 LK1 Aw1 x g1 cr1 R1 (ra spx : Z) :
  inv own' n M1 model1 LK1 Aw1 x g1 cr1 -> spx <= sp -> sp - SCR <= spx - 14336 -> spx mod 16 = 0 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spx ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  PMSPA.entryA AD L ar R1 M1 spx ra PQASA.PB_H /\ PGSA.ffroomB PQRA.FCM PQASA.PB_H FF LK1 /\ PMSPA.ffrsA FF spx.
