(* [comment removed for export] *)
Lemma RET own' n M1 model1 LK1 Aw1 x g1 cr1 (fx1 : FPState) R1 (pc : Z) (Wc : bv 32) :
  inv own' n M1 model1 LK1 Aw1 x g1 cr1 -> 0 <= n <= MAX ->
  fetch_word RSEGS (Z_to_bv 64 pc) = Some Wc -> is_ecall Wc = false -> decode_any Wc = Some (Jalr 0 1 0, 4%Z) ->
  regs_preserved R R1 -> getr R1 (reg 1) = getr R (reg 1) -> post R1 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc M1 model1) K.
