(* [comment removed for export] *)
Lemma buf_facts own' n M1 model1 LK1 Aw1 x g1 cr1 buf m :
  inv own' n M1 model1 LK1 Aw1 x g1 cr1 -> VA.rbufA M FF buf m os -> 0 < m ->
  (7036928 <= buf /\ buf + m <= ahl_ceil ar)
  /\ (forall q, buf <= q < buf + m -> exists c, 0 <= c < 256 /\ L5.u8_at RSEGS (mrestrict (ahid Aw1 model1) M1) q c)
  /\ (forall q, buf <= q < buf + m -> L5KA.zeros_at (mrestrict (ahid Aw1 model1) M1) (q / 8 + 2147450880) 1).
