(* [comment removed for export] *)
Lemma TAIL own' n M1 model1 LK1 Aw1 x g1 cr1 (fx1 : FPState) R1 (c : Z) :
  inv own' n M1 model1 LK1 Aw1 x g1 cr1 -> 0 <= n < MAX ->
  getr R1 (reg 1) = Z_to_bv 64 r -> getr R1 (reg 2) = Z_to_bv 64 sp ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 os -> getr R1 (reg 11) = Z_to_bv 64 c -> 0 <= c < 256 ->
  regs_preserved R R1 -> (forall R', regs_preserved R1 R' -> post R') ->
