Section PCall.
Variables (QPC QSCR : Z) (Qneed : Z -> Z) (QMX : Z) (qpre : bvmap 5 word -> mem -> list fframe -> Z -> Z -> Z -> Prop) (qpost : bvmap 5 word -> Prop).
Hypothesis Q : VA.pusherA RSEGS AD L ar HI QPC QSCR Qneed [] QMX qpre qpost.
Hypothesis QSCR16 : 0 <= QSCR /\ QSCR mod 16 = 0.
Hypothesis QMX0 : 0 <= QMX.
Hypothesis QNEED : forall k, In k PQRA.FCM -> Qneed k <= need k.

(* [comment removed for export] *)
Lemma q_entry own' n M1 model1 LK1 Aw1 x g1 cr1 R1 (ra spx : Z) :
  inv own' n M1 model1 LK1 Aw1 x g1 cr1 -> spx <= sp -> sp - SCR <= spx - QSCR -> spx mod 16 = 0 ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spx ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  VA.entryAs AD L ar R1 M1 spx ra QSCR /\ VA.ffroomN Qneed FF LK1 /\ PMSPA.ffrsA FF spx /\ VA.rcellA ar M1 spx so 8.
