Lemma TAILP own' n M1 model1 LK1 Aw1 x g1 cr1 (fx1 : FPState) R1 :
  inv own' n M1 model1 LK1 Aw1 x g1 cr1 -> 0 <= n -> n + QMX <= MAX -> QSCR <= SCR ->
  getr R1 (reg 1) = Z_to_bv 64 r -> getr R1 (reg 2) = Z_to_bv 64 sp ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  qpre R1 M1 FF so os sp ->
  regs_preserved R R1 -> (forall R', regs_preserved R1 R' -> qpost R' -> post R') ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 QPC M1 model1) K.
Proof using All.
