(* [comment removed for export] *)
Definition grisu3_runCA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : mem) (sp ra buf lenp kp u : Z),
    getr R 2%bv = Z_to_bv 64 sp -> getr R 1%bv = Z_to_bv 64 ra -> L5.ra_ok ra ->
    getr R 10%bv = Z_to_bv 64 buf -> getr R 11%bv = Z_to_bv 64 lenp -> getr R 12%bv = Z_to_bv 64 kp ->
    getr (@fp_regs fx) 10%bv = Z_to_bv 64 u -> 1 <= u < 2 ^ 63 -> frm_zero (@fp_csr fx) ->
    VA.IMG_HI_A + VA.G_SCR <= sp -> sp <= 2 ^ 47 -> sp mod 16 = 0 -> VA.bigapart (sp - VA.G_SCR) VA.G_SCR ->
    L5.writable segs M (sp - VA.G_SCR) VA.G_SCR -> L5.defined M (sp - VA.G_SCR) VA.G_SCR ->
    VA.IMG_HI_A <= buf -> buf + VA.G_BUF <= 2 ^ 47 -> buf mod 8 = 0 -> VA.bigapart buf VA.G_BUF -> L5.writable segs M buf VA.G_BUF -> L5.defined M buf VA.G_BUF ->
    VA.IMG_HI_A <= lenp -> lenp + 4 <= 2 ^ 47 -> VA.bigapart lenp 4 -> L5.writable segs M lenp 4 -> L5.defined M lenp 4 ->
    VA.IMG_HI_A <= kp -> kp + 4 <= 2 ^ 47 -> VA.bigapart kp 4 -> L5.writable segs M kp 4 -> L5.defined M kp 4 ->
    (sp <= buf \/ buf + VA.G_BUF <= sp - VA.G_SCR) -> (sp <= lenp \/ lenp + 4 <= sp - VA.G_SCR) -> (sp <= kp \/ kp + 4 <= sp - VA.G_SCR) ->
    (kp + 4 <= buf \/ buf + VA.G_BUF <= kp) -> (lenp + 4 <= buf \/ buf + VA.G_BUF <= lenp) -> (kp + 4 <= lenp \/ lenp + 4 <= kp) ->
    L5.img_clear M 0x10000 0x158000 -> L5.u64_at segs M VA.CELL_SB_A SB ->
    L5KA.zeros_at M (kp / 8 + SB) 1 -> L5KA.zeros_at M (lenp / 8 + SB) 1 -> L5KA.zeros_at M (buf / 8 + SB) 3 ->
    L5KA.zeros_at M (VA.TABF_A / 8 + SB) 687 -> L5KA.zeros_at M (VA.TABE_A / 8 + SB) 343 ->
    exists (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (res len k : Z),
      mem_grows M M'
      /\ (forall a : word, ~ (sp - VA.G_SCR <= bv_unsigned a < sp) -> ~ (buf <= bv_unsigned a < buf + VA.G_BUF) ->
                           ~ (lenp <= bv_unsigned a < lenp + 4) -> ~ (kp <= bv_unsigned a < kp + 4) -> M' a = M a)
      /\ (forall i : Z, 0 <= i < 2 ^ 64 -> ~ (sp - VA.G_SCR <= i < sp) -> ~ (buf <= i < buf + VA.G_BUF) ->
                         ~ (lenp <= i < lenp + 4) -> ~ (kp <= i < kp + 4) -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
      /\ msteps segs (st fx R pc M) (st fx' R' ra M')
      /\ (forall x, In x VA.G_CS -> getr R' (reg x) = getr R (reg x))
      /\ getr R' 10%bv = Z_to_bv 64 res /\ (res = 0 \/ res = 1)
      /\ L5.u32_at segs M' lenp len /\ 1 <= len <= 21 /\ L5.u32_at segs M' kp k /\ -343 <= k <= 309
      /\ L5.defined M' (sp - VA.G_SCR) VA.G_SCR /\ frm_zero (@fp_csr fx')
      /\ digits_at segs M' buf len.

(* [comment removed for export] *)
Definition pusherAC (pc scr : Z) (need : Z -> Z) (W : list L5.range) (mx : Z)
           (pre : bvmap 5 word -> mem -> list fframe -> Z -> Z -> Z -> Prop) (post : bvmap 5 word -> Prop) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : mem) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (so os sp r SM g : Z) (x : PM.vstr) (bs : list Z),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    VA.entryAs A L ar R M sp r scr -> VA.ffroomN need FF LK -> ffrsA FF sp -> sp mod 16 = 0 ->
    pre R M FF so os sp ->
    VA.rcellA ar M sp so 8 -> so mod 8 = 0 -> L5.u64_at segs M so os -> (so + 8 <= os \/ os + 24 <= so) ->
    aobjA FF os 24 -> os mod 8 = 0 -> kstr_at M os x -> kcontent M os x bs -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX -> PM.vs_size x + mx <= SM ->
    PMSTA.base_okA segs A M ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks HV SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit) (ds : list Z),
        regs_preserved R R' -> post R' -> kstr_at M' os x' -> kcontent M' os x' (bs ++ ds) -> NEM.ascii ds -> PQMA.ks_ok SM x' g' ->
        PM.vs_size x <= PM.vs_size x' <= PM.vs_size x + mx ->
        L5CA.ahpres L ar LB FF sp scr ((os, 24) :: W) M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks HV SM x g)) (PMSPA.scA L (PQMA.pot_ks HV SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.

(* [comment removed for export] *)
Definition fe_specCA (pc : Z) : Prop :=
  pusherAC pc VA.FE_SCR VA.N1 [] VA.FE_MAX
    (fun R _ _ so _ _ => exists k, getr R 10%bv = Z_to_bv 64 k /\ -999 <= k <= 999 /\ getr R 11%bv = Z_to_bv 64 so)
    (fun _ => True).

(* [comment removed for export] *)
Definition pr_specCA (pc : Z) : Prop :=
  pusherAC pc VA.PR_SCR VA.N1 [] VA.PR_MAX
    (fun R M FF so os sp => exists buf len k, getr R 10%bv = Z_to_bv 64 buf /\ getr R 11%bv = Z_to_bv 64 len /\ getr R 12%bv = Z_to_bv 64 k
        /\ getr R 13%bv = Z_to_bv 64 (-4) /\ getr R 14%bv = Z_to_bv 64 17 /\ getr R 15%bv = Z_to_bv 64 so
        /\ 1 <= len <= 21 /\ -400 <= k <= 400 /\ VA.rbufA M FF buf VA.G_BUF os /\ digits_at segs M buf len)
    (fun _ => True).

