Definition db_specCA (pc : Z) : Prop :=
  pusherAC pc VA.DB_SCR VA.N1 [] VA.DB_MAX
    (fun R M FF so os sp => exists buf n dp, getr R 10%bv = Z_to_bv 64 buf /\ getr R 11%bv = Z_to_bv 64 n /\ getr R 12%bv = Z_to_bv 64 dp /\ getr R 13%bv = Z_to_bv 64 so
        /\ 0 <= n <= WDL.SNP_MAX /\ 0 <= dp < 256 /\ VA.rbufA M FF buf n os)
    (fun _ => True).

(* [comment removed for export] *)
Definition dgf_specCA (pc : Z) : Prop :=
  pusherAC pc VA.DGF_SCR VA.DGF_N (VA.ERRNO_W (pa_tp A)) VA.DG_MAX
    (fun R _ _ so _ _ => exists dp, getr R 10%bv = Z_to_bv 64 dp /\ 0 <= dp < 256 /\ getr R 11%bv = Z_to_bv 64 so)
    (fun R' => getr R' 10%bv = Z_to_bv 64 1).
Definition dgt_specCA (pc : Z) : Prop :=
  pusherAC pc VA.DGT_SCR VA.DGT_N (VA.ERRNO_W (pa_tp A)) VA.DG_MAX
    (fun R _ _ so _ _ => exists dp, getr R 10%bv = Z_to_bv 64 dp /\ 0 <= dp < 256 /\ getr R 11%bv = Z_to_bv 64 so)
    (fun R' => getr R' 10%bv = Z_to_bv 64 1).

(* [comment removed for export] *)
Definition wd_specCA (pc : Z) : Prop :=
  pusherAC pc VA.WD_SCR VA.WD_N (VA.ERRNO_W (pa_tp A)) WD.WD_MAX
    (fun R M _ so os sp => exists o, getr R 10%bv = Z_to_bv 64 o /\ getr R 11%bv = Z_to_bv 64 so /\ VA.rcellA ar M sp o 12 /\ VA.wd_atA segs M o
        /\ (o + 12 <= os \/ os + 24 <= o))
    (fun _ => True).

