(* [comment removed for export] *)
Definition ann_shrink_lv_spec (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (v b k old : Z) (stk : list PQMA.alvl) (sp r : Z),
    ri_inv HI (PQMA.lvec_own b k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA A L ar R M sp r 0 -> PMSPA.ffrsA FF sp ->
    getr R 10%bv = Z_to_bv 64 v -> getr R 11%bv = Z_to_bv 64 old -> PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> PMSPA.accA M v 24 ->
    Z.of_nat (length stk) <= old <= 2 ^ k ->
    (* [comment removed for export] *)
    L5.u64_at segs M v b -> L5.u64_at segs M (v + 8) (b + LSZ * Z.of_nat (length stk)) -> L5.u64_at segs M (v + 16) (b + LSZ * 2 ^ k) ->
    0 <= k <= 11 -> b mod 16 = 0 -> L5.defined M b (LSZ * 2 ^ k) -> PMSPA.accA M b (LSZ * old) -> PMSPA.annA M b (LSZ * old) (LSZ * 2 ^ k) ->
    (forall i, (i < length stk)%nat -> PQMA.alvl_at segs M (b + LSZ * Z.of_nat i) (nth i stk PQMA.lv_root)) ->
