Module PQAKZC3.
Abbreviation RSEGS := Asan.M.loaded_segments.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Section Kit.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (HI : asan_iface).

(* [comment removed for export] *)
Definition gb_specCA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o need sp r SM g : Z) (x : PM.vstr) (bs : list Z),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp -> getr R (reg 4) = Z_to_bv 64 (hl_tp L) ->
    L5CA.astk ar M sp PQAKZ3.GB_SCR ->
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 (PM.vs_cap x) -> getr R (reg 12) = Z_to_bv 64 (need - PM.vs_cap x) ->
    getr R (reg 13) = Z_to_bv 64 (PM.vs_size x) -> getr R (reg 14) = Z_to_bv 64 (PM.vs_size x) -> getr R (reg 15) = Z_to_bv 64 0 ->
    PQMA.kstr_at RSEGS PMSPA.accA M o x -> NEM.kcontent RSEGS M o x bs -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX -> PM.vs_cap x < need <= SM ->
    PMSPA.aobjA FF o 24 -> o mod 8 = 0 ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (B A : Z) (cr' : credit),
        regs_preserved R R' -> A = PQASA.gcount (PM.vs_cap x) need ->
        L5.defined M' o 24 -> PMSPA.accA M' o 24 -> L5.u64_at RSEGS M' o (A + 1) -> L5.u64_at RSEGS M' (o + 16) B ->
        L5.defined M' B A -> PMSPA.accA M' B A -> L5.bytes_at RSEGS M' B bs ->
        PQMA.ks_ok SM (PM.VLong A need B) (g + 1) -> need < A -> 26 <= A <= PQMA.KCAP -> A mod 8 = 0 ->
        L5CA.ahpres L ar LB FF sp PQAKZ3.GB_SCR [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM (PM.VLong A need B) (g + 1))) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI ((B, A) :: LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R pc M model) K.


(* [comment removed for export] *)
Definition sc_specCA (pc : Z) : Prop :=
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LB : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (o q n sp r SM g : Z) (x : PM.vstr) (bs sbs : list Z),
    ri_inv HI (PM.vs_own x ++ LB) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp -> getr R (reg 4) = Z_to_bv 64 (hl_tp L) ->
    L5CA.astk ar M sp PQAKZ3.SC_SCR ->
    getr R (reg 10) = Z_to_bv 64 o -> getr R (reg 11) = Z_to_bv 64 n -> getr R (reg 12) = Z_to_bv 64 (PM.vs_size x) ->
    getr R (reg 13) = Z_to_bv 64 q -> getr R (reg 14) = Z_to_bv 64 (q + n) ->
    0 < n -> PM.vs_size x + n <= SM -> PQASCA.src_okCA RSEGS L HI M LB FF q n sbs -> (q + n <= o \/ o + 24 <= q) ->
    PMSPA.aobjA FF o 24 -> o mod 8 = 0 -> PQMA.kstr_at RSEGS PMSPA.accA M o x -> NEM.kcontent RSEGS M o x bs -> PQMA.ks_ok SM x g -> SM <= PQASA.SMMAX ->
    PMSP.credit_le (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (x' : PM.vstr) (g' : Z) (cr' : credit),
        regs_preserved R R' -> PQMA.kstr_at RSEGS PMSPA.accA M' o x' -> NEM.kcontent RSEGS M' o x' (bs ++ sbs) -> PQMA.ks_ok SM x' g' -> PM.vs_size x' = PM.vs_size x + n ->
        (PM.vs_size x + n <= PM.vs_cap x -> PM.vs_own x' = PM.vs_own x /\ g' = g) ->
        L5CA.ahpres L ar LB FF sp PQAKZ3.SC_SCR [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x g)) (PMSPA.scA L (PQMA.pot_ks (PMSPA.HV L ar) SM x' g')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vs_own x' ++ LB) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R pc M model) K.

End Kit.
End PQAKZC3.

