Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMA.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Let LYa := PMA.ly_as0 L C LY.
Local Notation mrun_pre := (PNRNA.mrun_pre RSEGS AD AQ AAD AE L ar).
Local Notation mrun_fin := (PNRNA.mrun_fin RSEGS AD AQ AAD AE L ar).
Local Notation pot_runA := (PNRNA.pot_runA L ar).
Local Notation ae_atA := (NEMA.ae_atA RSEGS AD AE L ar (qa_vp_adaptor AQ)).

(* [comment removed for export] *)
Lemma fin_mk LB1 FFx spx scr Wc (M1 M4 : mem) fb s1 s4 st1 st4 str sm1 sm4 e1 e4 b1 b4 cat :
  (forall f, In f FFx -> 0 <= ff_addr f /\ ff_addr f + ff_bytes (ff_class f) <= 2 ^ 47) ->
  ek L ar LB1 FFx spx scr Wc M1 M4 -> PMKA.wapp Wc -> PQRA.frame_okM FFx fb ->
  (forall i, fb + 1088 <= i < fb + 1096 -> L5.outside Wc i) ->
  mrun_fin M1 fb s1 st1 str sm1 e1 b1 cat ->
  mparser_at M4 (fb + 592) (fb + 96) s4 -> ae_atA M4 (fb + 592 + 400) (fb + 496) (fb + 432) st4 -> PM.iss_at RSEGS AD accA M4 (fb + 96) str sm4 ->
  PQMA.mgrow_ok s4 -> NEMA.ae_ok st4 -> PMSTA.base_okA RSEGS AD M4 -> PQSTA.err_okA RSEGS AD AAD AQ M4 e4 -> ec_stateA M4 (fb + 1232) b4 cat ->
