(* [comment removed for export] *)
Lemma fin_keep LB1 FFx spx scr Wc (M1 M4 : mem) fb s1 st str sm1 e1 b1 cat :
  (forall f, In f FFx -> 0 <= ff_addr f /\ ff_addr f + ff_bytes (ff_class f) <= 2 ^ 47) -> (forall b, In b LB1 -> 0 <= fst b /\ fst b + snd b <= 2 ^ 47) ->
  ek L ar LB1 FFx spx scr Wc M1 M4 -> PMKA.wapp Wc -> PQRA.frame_okM FFx fb -> incl (mown s1 st) LB1 -> incl (PM.vs_own str) LB1 ->
  (forall i, fb + 32 <= i < fb + 2040 -> L5.outside Wc i) -> (forall a, 65536 <= a < 7036928 -> L5.outside Wc a) ->
  (forall B m, In (B, m) LB1 -> forall i, B <= i < B + m -> L5.outside Wc i) ->
