(* [comment removed for export] *)
Lemma binv_callee BX BXa BX1 Mc modelc LKc crc Ac M1 model1 LK1 cr1 A1 SCRc (Wc : list L5.range) :
  binvG own BX Mc modelc LKc crc Ac ->
  L5CA.ahpres L ar (BXa ++ LBX) FF spc SCRc Wc Mc M1 ->
  ri_inv HI (BX1 ++ LBX) FF LK1 cr1 A1 M1 (vml_of model1) -> L5CA.amodel_ok A1 model1 -> model_rt modelc model1 -> incl Ac A1 -> incl LK1 LKc ->
  0 <= SCRc -> sp - SCR <= spc - SCRc ->
  (forall rr a, In rr Wc -> L5.in_rng rr a -> ~ (spc <= a < sp)) ->
  (forall a, aclient L ar LBX FF sp SCR a -> L5.outside WR a -> L5.outside Wc a) ->
  binvG own BX1 M1 model1 LK1 cr1 A1 /\ (forall a, spc <= a < sp -> M1 (Z_to_bv 64 a) = Mc (Z_to_bv 64 a)).
Proof using All.
