  regs_preserved R R5 -> getr R5 (reg 1) = getr R (reg 1) ->
  ( (b5 = true)
    \/ (b5 = false /\ PQMA.cpl s5 (NEMA.ae_a sa5) /\ PQMA.acct n s5 (NEMA.ae_a sa5) sm5 /\ NEMA.oacct n s5 sa5 sm5 /\ NEMA.ebound sa5 /\ NEMA.bal sa5
        /\ PQRA.minv_d d s5 /\ (forall Mf, prog R5 Mf s s5 sa sa5 sm sm5) /\ PQRA.room_keep s s5 sm sm5) ) ->
  PMSP.credit_keep cr cr5 (pot_runA s sa) (pot_runA s5 sa5) ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : mem) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (s' : PQMA.mpst) (st' : NEMA.aest)
          (sm' : PM.strm) (e' b' : bool) (cr' : credit),
      regs_preserved R R' ->
      PNRNA.mrun_post_d RSEGS AD AQ AAD AE L ar d prog R' M' fb s s' sa st' str sm sm' e e' eb b' cat n ->
      L5CA.ahpres L ar LBX FF sp SCR (W_mrun fb) M M' ->
      PMSP.credit_keep cr cr' (pot_runA s sa) (pot_runA s' st') ->
      model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' -> ri_inv HI (mown s' st' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx5 R5 pc5 M5 model5) K.
Proof using All.
