Module PENTBAF.
Section WithImage.
Context {SCFG_P : ScfgP}.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable L : asan_layout.
Variable ar : asan_run.
Variable HI : asan_iface.
Abbreviation sink_atA := (NESKA.sink_atA segs L ar).
Abbreviation entryA := (PMSPA.entryA A L ar).
Abbreviation cfg := (@PMSPA.cfg segs).

(* [comment removed for export] *)
Definition ntbf_specA (pc kb : Z) (P : NESKA.sink_policyA) : Prop :=
  NESKA.spa_mode P ->
  forall (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
         (LBX : list (Z * Z)) (FF LK : list fframe) (Aw : list (Z * Z)) (cr : credit) (rr o sp r h : Z) (k : NESK.sink),
    ri_inv HI (NESK.sink_own k ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    entryA R M sp r 2 -> PMSPA.ffroomA 2 FF LK -> PMSPA.ffrsA FF sp -> sp mod 16 = 0 ->
    getr R 10%bv = Z_to_bv 64 rr -> L5.u64_at segs M rr o -> rr mod 8 = 0 -> PMSPA.aobjA FF rr 8 -> PMSPA.accA M rr 8 ->
    (o + 24 <= rr \/ rr + 8 <= o) ->
    sink_atA P M o k -> PMSPA.aobjA FF o 24 -> o mod 8 = 0 ->
    NESKA.spa_hb P h -> NESK.sk_z k + kb <= h ->
    PMSP.credit_le (NESKA.spa_pot P (NESK.sk_c k)) cr ->
    (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (LK' : list fframe) (Aw' : list (Z * Z)) (cr' : credit) (k' : NESK.sink),
        regs_preserved R R' -> NESK.sk_z k' = NESK.sk_z k + kb ->
        sink_atA P M' o k' ->
        L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 2) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (NESKA.spa_pot P (NESK.sk_c k)) (NESKA.spa_pot P (NESK.sk_c k')) ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (NESK.sink_own k' ++ LBX) FF LK' cr' Aw' M' (vml_of model') ->
        srealizes segs SCFG (@cfg fx' R' r M' model') K) ->
    srealizes segs SCFG (@cfg fx R pc M model) K.
End WithImage.
End PENTBAF.

End PnAEncNtbFSpec.
