Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (LR : HAR.layoutR) (HIk : list (list Z) -> asan_iface) (D0 D1 : list (list Z)).
Hypothesis LY : PMA.layout L C.
Hypothesis FAMok : HAR.asan_famR_ok L ar C SCFG LR HIk.
Hypothesis INC01 : incl D0 D1.
Local Notation HI := (HIk D1).
Local Notation HIok := (HAR.fr_base L ar C SCFG LR HIk FAMok D1).
Local Notation HI0 := (HIk D0).
Local Notation HIok0 := (HAR.fr_base L ar C SCFG LR HIk FAMok D0).
Let LYa := PMA.ly_as0 L C LY.
Local Notation mrun_pre := (PNRNA.mrun_pre RSEGS AD AQ AAD AE L ar).
Local Notation pot_runA := (PNRNA.pot_runA L ar).
Local Notation ae_atA := (NEMA.ae_atA RSEGS AD AE L ar (qa_vp_adaptor AQ)).

(* [comment removed for export] *)
(* [comment removed for export] *)
Lemma ae_keep LB1 FFx spx scr Wc (M1 M4 : mem) fb st :
  (forall f, In f FFx -> 0 <= ff_addr f /\ ff_addr f + ff_bytes (ff_class f) <= 2 ^ 47) -> (forall b, In b LB1 -> 0 <= fst b /\ fst b + snd b <= 2 ^ 47) ->
  ek L ar LB1 FFx spx scr Wc M1 M4 -> PMKA.wapp Wc -> PQRA.frame_okM FFx fb -> incl (NEMA.aeown st) LB1 ->
  (forall i, (fb + 432 <= i < fb + 456 \/ fb + 496 <= i < fb + 552 \/ fb + 992 <= i < fb + 1096) -> L5.outside Wc i) ->
  (forall B m, In (B, m) (NEMA.aeown st) -> forall i, B <= i < B + m -> L5.outside Wc i) ->
  ae_atA M1 (fb + 592 + 400) (fb + 496) (fb + 432) st -> ae_atA M4 (fb + 592 + 400) (fb + 496) (fb + 432) st.
Proof.
