Definition with_tb (s : PQMA.mpst) (x : PM.vstr) : PQMA.mpst :=
  PQMA.MPST (PQMA.p_more s) (PQMA.p_done s) (PQMA.p_depth s) (PQMA.p_src s) x (PQMA.p_tg s) (PQMA.p_bb s) (PQMA.p_bg s)
            (PQMA.p_sb s) (PQMA.p_sk s) (PQMA.p_stk s).
(* [comment removed for export] *)
Definition tb_rest_own (s : PQMA.mpst) : list (Z * Z) :=
  PM.src_own (PQMA.p_src s) ++ PQMA.mvec_own (PQMA.p_sb s) (PQMA.p_sk s) ++ PGV8.v8_own (PQMA.p_bb s).

