(* [comment removed for export] *)
(* [comment removed for export] *)
Section OK.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable vp : Z.
Variables (L : asan_layout) (ar : asan_run) (HI : asan_iface).
Variables (op ois lo hi : Z) (s : PQMA.mpst) (x' : PM.vstr).
Hypothesis WF : HAJ.rt_wfR L ar HI.
Hypothesis LAY : lo <= op /\ op + PQMA.PSIZE <= hi /\ lo <= ois /\ ois + 272 <= hi /\ hi <= ar_sptop ar /\ hi <= 2 ^ 47
                 /\ op mod 8 = 0 /\ ois mod 8 = 0 /\ 4096 <= lo.
Hypothesis DIS : op + PQMA.PSIZE <= ois \/ ois + 272 <= op.

Theorem tb_owner_updA (LBF LBX OB : list (Z * Z)) (FF LK : list fframe) (cr : credit) (Aw : list (Z * Z)) (M M' : word -> option byte) (V : vml) (sp scr : Z) :
  ri_inv HI LBF FF LK cr Aw M V -> incl (OB ++ LBX) LBF -> PGSA.ofr FF lo hi -> OB = tb_rest_own s ->
  L5CA.ahpres L ar (OB ++ LBX) FF sp scr [(op + PQMA.OFF_TB, 24)] M M' ->
  PQMA.mparser_at segs A accA annA vp M op ois s -> PM.vstr_at segs accA M' (op + PQMA.OFF_TB) x' ->
