Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac lia := try match goal with H : PQMA.mvec_at _ _ _ _ _ _ _ _ |- _ => clear H end; Stdlib.micromega.Lia.lia.
Local Ltac mod8 H := match goal with |- (?o + ?c) mod 8 = 0 => let q := eval vm_compute in (Z.div c 8) in
  replace (o + c) with (o + q * 8) by lia; rewrite Z_mod_plus_full; exact H end.

Module PQAKWV.
Abbreviation accA := PMSPA.accA.
Abbreviation annA := PMSPA.annA.
Abbreviation apart := PNOFA.apart.

(* [comment removed for export] *)
(* [comment removed for export] *)
Section VUpd.
Local Ltac lu := unfold PQMA.PSIZE, PQMA.OFF_SRC, PQMA.OFF_MAXD, PQMA.OFF_BB, PQMA.OFF_TB, PQMA.OFF_STK in *; lia.
Variable segs : list Segment.
Variable A : pm_addrs.
Variable vp : Z.
Abbreviation mparser_at := (PQMA.mparser_at segs A accA annA vp).
Variables (L : asan_layout) (ar : asan_run).
Variables (LBX OB : list (Z * Z)) (FF : list fframe) (sp scr : Z) (Wx : list L5.range) (M M' : word -> option byte).
Variables (op ois lo hi : Z) (s : PQMA.mpst) (src src' : PM.srcst) (x x' : PGV8.v8) (g g' : Z).
Let LB : list (Z * Z) := OB ++ LBX.
Let W : list L5.range := PGS.W_srcfG (op + PQMA.OFF_SRC) ois ++ [(op + PQMA.OFF_BB, 24)] ++ Wx.

Hypothesis Hlay : lo <= op /\ op + PQMA.PSIZE <= hi /\ lo <= ois /\ ois + 272 <= hi /\ hi <= 2 ^ 47 /\ 0 <= lo.
Hypothesis Hdis : op + PQMA.PSIZE <= ois \/ ois + 272 <= op.
Hypothesis EOB : OB = PQMA.vec_rest_own s.
Hypothesis HFA : app_mem lo (hi - lo).
Hypothesis HFR : forall a, lo <= a < hi -> aclient L ar LB FF sp scr a /\ aclient L ar LB FF sp scr (S a).
Hypothesis HBA : forall b, In b LB -> 0 < snd b /\ fst b mod 16 = 0 /\ app_mem (fst b) (snd b).
Hypothesis HA : forall b, In b OB -> apart (fst b) (snd b) lo (hi - lo).
Hypothesis HC : Forall (fun r => apart (fst r) (snd r) lo (hi - lo) /\ (forall b, In b OB -> apart (fst r) (snd r) (fst b) (snd b)) /\ app_mem (fst r) (snd r)) Wx.
Hypothesis HP : L5CA.ahpres L ar LB FF sp scr W M M'.
Hypothesis HOW : mparser_at M op ois (PQMA.with_src_bb s src x g).
Hypothesis HSRC : PM.src_fields_at segs accA M' (op + PQMA.OFF_SRC) ois (ois + 16) src'.
Hypothesis HBB : PGV8.v8_at segs accA annA M' (op + PQMA.OFF_BB) x'.

