Definition margs_riR (RS : list Z) (R : bvmap 5 word) (fb : Z) (s : PQMA.mpst) (st : NEMA.aest) (sm : PM.strm) (n : Z) : Prop :=
  PNRNA.margs_ri AD AQ R fb s st sm n /\ In (bv_unsigned (getr R 1%bv)) RS /\ bv_unsigned (getr R 8%bv) <> bv_unsigned (getr R 2%bv) + 8.

Definition read_item_specFR : Prop :=
  PNRNA.mrun_specF_d RSEGS AD AQ AAD NemLayoutA.NEADDR_A L ar HIk tsp (qa_read_item AQ) PNRNA.RI_H 0 (margs_riR RS_A) PNRNA.mprog_item.
