(* [comment removed for export] *)
Lemma CALL n M1 model1 LK1 Aw1 x g1 cr1 (fx1 : FPState) R1 (ra c : Z) :
  inv own n M1 model1 LK1 Aw1 x g1 cr1 -> 0 <= n < MAX ->
  getr R1 (reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr R1 (reg 2) = Z_to_bv 64 spc ->
  getr R1 (reg 3) = Z_to_bv 64 (pa_gp AD) -> getr R1 (reg 4) = Z_to_bv 64 (hl_tp L) ->
  getr R1 (reg 10) = Z_to_bv 64 os -> getr R1 (reg 11) = Z_to_bv 64 c -> 0 <= c < 128 ->
  (forall (fx2 : FPState) R2 (M3 : mem) model3 LK3 Aw3 x3 g3 cr3,
      regs_preserved R1 R2 -> inv own (n + 1) M3 model3 LK3 Aw3 x3 g3 cr3 ->
      (forall a, spc <= a < sp -> M3 (Z_to_bv 64 a) = M1 (Z_to_bv 64 a)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx2 R2 ra M3 model3) K) ->
